contracts/MvaultBoardMatrix.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// ─────────────────────────────────────────────────────────────────────────────
// MvaultBoardMatrix
//
// Board Matrix System (10 levels):
//   Users fund entry using their BTC pool balance (accumulated from MVT sells).
//   Each board needs 12 members to complete.
//   Pool = boardPrice × 9 members.
//
//   Boards 1–9 on completion:
//     40% → owner reward      (USDT sent directly to owner)
//     40% → next board entry  (auto-enters owner into next level)
//     20% → liquidity address
//
//   Board 10 (final) on completion:
//     87.5% → owner reward
//      6.25% → system address
//      6.25% → liquidity address
//
// Entry:
//   MvaultContract calls enterBoard(user, 1) after deducting from btcPoolBalance.
//   USDT is transferred from MvaultContract to this contract before calling enterBoard.
// ─────────────────────────────────────────────────────────────────────────────

interface IMvaultBoardCallback {
    function creditBoardReward(address user, uint256 usdtAmount, uint256 boardLevel) external;
}

contract MvaultBoardMatrix is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    struct BoardMatrix {
        address owner;
        uint256 filledCount;
        bool    completed;
    }

    uint256 public constant TOTAL_BOARDS            = 10;
    uint256 public constant BOARD_MEMBERS_REQUIRED  = 12;
    uint256 public constant BOARD_POOL_MEMBERS      = 9;   // used for pool calculation
    uint256 public constant BOARD_REWARD_RATE_BP    = 4000; // 40%
    uint256 public constant BOARD_NEXT_POOL_RATE_BP = 4000; // 40%
    uint256 public constant BOARD_LIQUIDITY_RATE_BP = 2000; // 20%
    uint256 public constant BOARD_10_REWARD_RATE_BP    = 8750; // 87.50%
    uint256 public constant BOARD_10_SYSTEM_RATE_BP    = 625;  //  6.25%
    uint256 public constant BOARD_10_LIQUIDITY_RATE_BP = 625;  //  6.25%
    uint256 public constant BASIS_POINTS            = 10000;

    mapping(uint256 => BoardMatrix[]) internal _boardMatrices;
    mapping(uint256 => uint256) public boardCurrentIndex;

    // Per-user board tracking
    mapping(address => uint256) public boardEntryCount;
    mapping(address => uint256) public totalBoardRewardsEarned;

    // Pending rewards: USDT already transferred to MvaultContract but balance not yet credited
    // (occurs when creditBoardReward callback is blocked by MvaultContract's reentrancy guard)
    mapping(address => uint256) public pendingBoardRewards;
    mapping(address => uint256) public pendingBoardLevel;

    uint256[11] public boardPrices; // index 1–10

    IERC20  public immutable usdtToken;
    address public mvaultContract;
    address public liquidityAddress;
    address public systemAddress;

    event BoardEntered(address indexed user, uint256 indexed boardLevel, uint256 matrixIndex);
    event BoardCompleted(address indexed owner, uint256 indexed boardLevel, uint256 reward, uint256 liquidity);
    event BoardHandlerSet(address indexed mvaultContract);
    event LiquidityAddressSet(address indexed addr);
    event SystemAddressSet(address indexed addr);
    event PendingBoardReward(address indexed user, uint256 amount, uint256 boardLevel);
    event PendingBoardRewardSettled(address indexed user, uint256 amount);

    modifier onlyMvault() {
        require(msg.sender == mvaultContract || msg.sender == owner(), "NA");
        _;
    }

    // ─────────────────────────────────────────────────────────────────────────
    constructor(address _usdt) Ownable(msg.sender) {
        require(_usdt != address(0), "ZA");
        usdtToken = IERC20(_usdt);

        // Board prices derived from 40/40/20 split: price[N+1] = price[N] × 9 × 0.4 = price[N] × 3.6
        // Using 18-decimal USDT (1e18 = $1)
        boardPrices[1]  = 50       * 1e18;
        boardPrices[2]  = 180      * 1e18;
        boardPrices[3]  = 648      * 1e18;
        boardPrices[4]  = 2333     * 1e18;
        boardPrices[5]  = 8398     * 1e18;
        boardPrices[6]  = 30233    * 1e18;
        boardPrices[7]  = 108839   * 1e18;
        boardPrices[8]  = 391821   * 1e18;
        boardPrices[9]  = 1410555  * 1e18;
        boardPrices[10] = 5077998  * 1e18;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ADMIN SETTERS
    // ─────────────────────────────────────────────────────────────────────────

    function setMvaultContract(address _mvault) external onlyOwner {
        require(_mvault != address(0), "ZA");
        mvaultContract = _mvault;
        emit BoardHandlerSet(_mvault);
    }

    function setLiquidityAddress(address _addr) external onlyOwner {
        require(_addr != address(0), "ZA");
        liquidityAddress = _addr;
        emit LiquidityAddressSet(_addr);
    }

    function setSystemAddress(address _addr) external onlyOwner {
        require(_addr != address(0), "ZA");
        systemAddress = _addr;
        emit SystemAddressSet(_addr);
    }

    function setBoardPrice(uint256 _level, uint256 _price) external onlyOwner {
        require(_level >= 1 && _level <= TOTAL_BOARDS, "BL");
        require(_price > 0, "P0");
        boardPrices[_level] = _price;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ENTRY POINT (called by MvaultContract)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Enter a user into the board at the given level.
     *         USDT equal to boardPrices[boardLevel] must already be in this contract.
     *         Only callable by MvaultContract or owner.
     */
    function enterBoard(address _user, uint256 _boardLevel) external onlyMvault {
        require(_boardLevel >= 1 && _boardLevel <= TOTAL_BOARDS, "BL");
        _enterBoard(_user, _boardLevel);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INTERNAL LOGIC
    // ─────────────────────────────────────────────────────────────────────────

    function _enterBoard(address _user, uint256 _boardLevel) internal {
        // Create new board matrix slot for this user as owner
        _boardMatrices[_boardLevel].push(BoardMatrix({
            owner:       _user,
            filledCount: 0,
            completed:   false
        }));
        uint256 newIdx = _boardMatrices[_boardLevel].length - 1;
        boardEntryCount[_user]++;

        emit BoardEntered(_user, _boardLevel, newIdx);

        // Fill a slot in the current active board (if one exists ahead of this user's new slot)
        uint256 currentIdx = boardCurrentIndex[_boardLevel];
        if (currentIdx < newIdx) {
            BoardMatrix storage activeMatrix = _boardMatrices[_boardLevel][currentIdx];
            activeMatrix.filledCount++;

            if (activeMatrix.filledCount >= BOARD_MEMBERS_REQUIRED) {
                activeMatrix.completed = true;
                boardCurrentIndex[_boardLevel] = currentIdx + 1;
                _completeBoardMatrix(activeMatrix.owner, _boardLevel);
            }
        }
    }

    function _completeBoardMatrix(address _owner, uint256 _boardLevel) internal {
        uint256 totalPool = boardPrices[_boardLevel] * BOARD_POOL_MEMBERS;

        if (_boardLevel < TOTAL_BOARDS) {
            uint256 reward    = (totalPool * BOARD_REWARD_RATE_BP)    / BASIS_POINTS; // 40%
            // 40% (BOARD_NEXT_POOL_RATE_BP) stays in this contract to fund the owner's next board entry
            uint256 liquidity = (totalPool * BOARD_LIQUIDITY_RATE_BP) / BASIS_POINTS; // 20%

            // ── Credit reward ─────────────────────────────────────────────────
            _creditReward(_owner, reward, _boardLevel);

            // ── Send liquidity ────────────────────────────────────────────────
            if (liquidityAddress != address(0) && liquidity > 0) {
                usdtToken.safeTransfer(liquidityAddress, liquidity);
            }

            emit BoardCompleted(_owner, _boardLevel, reward, liquidity);

            // ── Auto-enter owner into next board (nextEntry stays in contract) ──
            // nextEntry amount is already held in this contract from previous collections.
            // We simply register the owner — no additional USDT transfer needed.
            _enterBoard(_owner, _boardLevel + 1);

        } else {
            // ── Final board (Level 10) ────────────────────────────────────────
            uint256 reward    = (totalPool * BOARD_10_REWARD_RATE_BP)    / BASIS_POINTS; // 87.5%
            uint256 systemFee = (totalPool * BOARD_10_SYSTEM_RATE_BP)    / BASIS_POINTS; //  6.25%
            uint256 liquidity = (totalPool * BOARD_10_LIQUIDITY_RATE_BP) / BASIS_POINTS; //  6.25%

            _creditReward(_owner, reward, _boardLevel);

            if (systemAddress != address(0) && systemFee > 0) {
                usdtToken.safeTransfer(systemAddress, systemFee);
            }
            if (liquidityAddress != address(0) && liquidity > 0) {
                usdtToken.safeTransfer(liquidityAddress, liquidity);
            }

            emit BoardCompleted(_owner, _boardLevel, reward, liquidity);
        }
    }

    /**
     * @dev Credit board reward. Transfers USDT to MvaultContract and calls the
     *      creditBoardReward callback to update the user's withdrawable balance.
     *
     *      If the callback reverts (e.g. MvaultContract's reentrancy guard is locked
     *      because we're inside enterBoardPool), the USDT is already safely in
     *      MvaultContract and the pending amount is stored here.
     *      Call settlePendingReward(user) once the lock is released.
     */
    function _creditReward(address _owner, uint256 _reward, uint256 _boardLevel) internal {
        if (_reward == 0) return;

        totalBoardRewardsEarned[_owner] += _reward;

        if (mvaultContract != address(0)) {
            // Transfer USDT to MvaultContract first — this is NOT rolled back if the
            // subsequent external call is caught by try/catch.
            usdtToken.safeTransfer(mvaultContract, _reward);

            // Try to credit the balance via callback. If MvaultContract's nonReentrant
            // guard is active (e.g. called from within enterBoardPool), this reverts.
            // We catch that and record the amount as pending — the USDT is already in
            // MvaultContract and will be credited when settlePendingReward is called.
            try IMvaultBoardCallback(mvaultContract).creditBoardReward(_owner, _reward, _boardLevel) {
                // success
            } catch {
                pendingBoardRewards[_owner] += _reward;
                pendingBoardLevel[_owner]    = _boardLevel;
                emit PendingBoardReward(_owner, _reward, _boardLevel);
            }
        } else {
            // Fallback: send directly to owner's wallet
            usdtToken.safeTransfer(_owner, _reward);
        }
    }

    /**
     * @notice Settle any pending board reward for `user`.
     *         The USDT was already forwarded to MvaultContract during board completion.
     *         This simply triggers the balance-credit callback once the reentrancy lock is free.
     *         Callable by anyone (permissionless — USDT is already secured in MvaultContract).
     */
    function settlePendingReward(address user) external nonReentrant {
        uint256 pending = pendingBoardRewards[user];
        require(pending > 0, "NP");
        uint256 level = pendingBoardLevel[user];
        pendingBoardRewards[user] = 0;
        pendingBoardLevel[user]   = 0;
        // USDT is already in MvaultContract — just trigger the balance credit
        IMvaultBoardCallback(mvaultContract).creditBoardReward(user, pending, level);
        emit PendingBoardRewardSettled(user, pending);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // VIEW FUNCTIONS
    // ─────────────────────────────────────────────────────────────────────────

    function getBoardPrice(uint256 _level) external view returns (uint256) {
        require(_level >= 1 && _level <= TOTAL_BOARDS, "BL");
        return boardPrices[_level];
    }

    function getBoardQueueLength(uint256 _level) external view returns (uint256) {
        return _boardMatrices[_level].length;
    }

    function getBoardMatrixInfo(uint256 _level, uint256 _index) external view returns (
        address owner,
        uint256 filledCount,
        bool    completed
    ) {
        require(_index < _boardMatrices[_level].length, "OB");
        BoardMatrix storage m = _boardMatrices[_level][_index];
        return (m.owner, m.filledCount, m.completed);
    }

    function getBoardCurrentIndex(uint256 _level) external view returns (uint256) {
        return boardCurrentIndex[_level];
    }

    function getUserBoardStats(address _user) external view returns (
        uint256 totalEntries,
        uint256 totalRewards
    ) {
        return (boardEntryCount[_user], totalBoardRewardsEarned[_user]);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ADMIN RECOVERY
    // ─────────────────────────────────────────────────────────────────────────

    function recoverToken(address _token, address _to, uint256 _amount) external onlyOwner {
        require(_to != address(0), "ZA");
        IERC20(_token).safeTransfer(_to, _amount);
    }
}

contracts/MvaultContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

// ─────────────────────────────────────────────
// MvaultToken interface (minimal surface needed)
// ─────────────────────────────────────────────
interface IMvaultToken {
    function addLiquidityAndMint(address to, uint256 usdtAmount) external;
    function sell(uint256 amount) external;
    function getBuyPrice() external view returns (uint256);
    function getSellPrice() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

// ─────────────────────────────────────────────
// MvaultBoardMatrix interface
// ─────────────────────────────────────────────
interface IMvaultBoardMatrix {
    function enterBoard(address user, uint256 boardLevel) external;
    function getBoardPrice(uint256 boardLevel) external view returns (uint256);
    function getBoardQueueLength(uint256 boardLevel) external view returns (uint256);
    function getBoardMatrixInfo(uint256 boardLevel, uint256 index) external view returns (address owner, uint256 filledCount, bool completed);
    function getBoardCurrentIndex(uint256 boardLevel) external view returns (uint256);
}

// ─────────────────────────────────────────────
// MvaultStaking interface (called by MvaultContract delegates)
// ─────────────────────────────────────────────
interface IMvaultStaking {
    function executeStake(address user, uint256 amount, bool isLocked) external;
    function executeUnstake(address user, uint256 stakeIndex) external;
    function executeConvertToLocked(address user, uint256 stakeIndex) external;
    function getStakeCount(address user) external view returns (uint256);
    function getStake(address user, uint256 index) external view returns (
        uint256 mvtAmount, uint256 usdtInvested, uint256 stakedAt, uint256 lockedSince, bool active
    );
    function getActiveStakes(address user) external view returns (
        uint256[] memory indices, uint256[] memory mvtAmounts,
        uint256[] memory usdtInvestedArr, uint256[] memory stakedAts, uint256[] memory lockedSinces
    );
}

contract MvaultContract is Ownable, ReentrancyGuard {

    // ── External contracts ────────────────────────────────────────────────────
    IERC20              public immutable usdtToken;
    IMvaultToken        public           mvaultToken;
    IMvaultBoardMatrix  public           boardHandler;
    IMvaultStaking      public           stakingModule;

    // ── Package constants ──────────────────────────────────────────────────────
    uint256 internal constant PRICE_STARTER  = 55  * 1e18;
    uint256 internal constant INCOME_STARTER = 165 * 1e18;
    uint256 internal constant PRICE_PRO      = 130 * 1e18;
    uint256 internal constant INCOME_PRO     = 390 * 1e18;

    // ── Pool allocation constants ──────────────────────────────────────────────
    uint256 internal constant LEVEL_ALLOC    = 30;
    uint256 internal constant COMMUNITY_ALLOC = 10;
    uint256 internal constant PLACEMENT_ALLOC = 20;
    uint256 internal constant ADMIN_ALLOC    = 20;
    uint256 internal constant RANK_ALLOC     = 10;
    // Liquidity 10% handled internally by MvaultToken (only 90% minted)
    uint256 internal constant BTC_POOL_RATE  = 10;

    // ── User record ───────────────────────────────────────────────────────────
    struct User {
        bool    isRegistered;
        bool    isActive;
        // Level / sponsor tree
        address sponsor;
        uint256 directCount;
        // Binary tree
        address binaryParent;
        bool    placedLeft;
        address leftChild;
        address rightChild;
        uint256 leftSubVolume;    // cumulative USDT activated in left binary subtree
        uint256 rightSubVolume;   // cumulative USDT activated in right binary subtree
        // Virtual MVT
        uint256 mvtBalance;       // available to sell
        uint256 totalReceived;    // lifetime MVT credited
        uint256 totalSold;        // lifetime MVT sold
        // USDT income
        uint256 incomeLimit;      // remaining USDT earning capacity (resets on rebirth)
        uint256 usdtBalance;      // withdrawable USDT
        uint256 rebirthPool;      // USDT accumulating toward next rebirth
        uint256 totalUsdtEarned;  // lifetime USDT received to usdtBalance
        // BTC pool (10% deducted from every sell, per user — like backup contract)
        uint256 btcPoolBalance;   // accumulated USDT for BTC purchase
        uint256 totalBtcEarned;   // lifetime BTC pool credits
        // Package
        uint256 packagePrice;     // activation price paid ($55 or $130)
        uint256 incomeLimitCap;   // max income per cycle (3 × packagePrice)
        // Rebirth
        address mainAccount;      // if sub-account → points to main; else address(0)
        uint256 rebirthCount;
        // Rank
        uint8   rank;             // reserved for rank system (not yet auto-computed)
        uint256 teamSalesUsdt;    // cumulative USDT activated in sponsor-tree downline
        // Meta
        uint256 joinedAt;
        // Profile
        string  displayName;
        string  email;
        string  phone;
        string  country;
        bool    profileSet;
        // BTC pool allocation rate: 10–80% (0 = default 10%)
        uint8   btcPoolRate;
    }

    mapping(address => User) public users;
    address[] public allUsers;
    uint256   public totalUsers;

    // ── Pool balances (virtual MVT) ───────────────────────────────────────────
    uint256 public reservePool;
    uint256 public adminPool;
    uint256 public rankPool;
    uint256 public communityPool;

    // Community wallet — receives 10% of grossMvt on every activation
    address public communityWallet;

    // Placement income config (binary tree, 30 levels)
    uint256[30] public placementRates; // basis points out of 10000; sum = 2000 (20%)
    uint256 public refsPerGroup;       // direct referrals required per 3-level group

    // Manager — can call admin setters without full owner powers
    address public manager;

    // ── Board Matrix tracking ──────────────────────────────────────────────────
    mapping(address => uint256) public boardEntryCount;
    mapping(address => uint256) public totalBoardRewardsEarned;


    // ── Transaction History (on-chain) ────────────────────────────────────────
    // txType constants
    uint8 internal constant TX_ACTIVATION        = 0;
    uint8 internal constant TX_LEVEL_INCOME      = 1;
    uint8 internal constant TX_LEVEL_MISSED      = 2;
    uint8 internal constant TX_PLACEMENT_INCOME  = 3;
    uint8 internal constant TX_PLACEMENT_MISSED  = 4;
    uint8 internal constant TX_SELL_MVT          = 5;
    uint8 internal constant TX_BTC_CREDITED   = 6;
    uint8 internal constant TX_USDT_WITHDRAW  = 7;
    uint8 internal constant TX_REACTIVATION   = 15;
    uint8 internal constant TX_RANK_INCOME    = 16;
    uint8 internal constant TX_BTC_WITHDRAW   = 8;
    uint8 internal constant TX_REBIRTH        = 9;
    uint8 internal constant TX_BOARD_ENTRY    = 10;
    uint8 internal constant TX_BOARD_REWARD   = 11;
    uint8 internal constant TX_STAKE          = 12;
    uint8 internal constant TX_UNSTAKE        = 13;
    uint8 internal constant TX_REBIRTH_CLAIM  = 14;

    struct TxRecord {
        uint8   txType;    // one of TX_* constants above
        uint32  ts;        // block.timestamp (safe until year 2106)
        uint256 amount;    // in token's native units
        uint8   level;     // level number (0 = N/A)
        address addr;      // counterpart address (from/to), address(0) if N/A
    }

    mapping(address => TxRecord[]) private _txRecords;

    function _recordTx(address user, uint8 txType, uint256 amount, uint8 level, address addr) internal {
        _txRecords[user].push(TxRecord({
            txType: txType,
            ts:     uint32(block.timestamp),
            amount: amount,
            level:  level,
            addr:   addr
        }));
    }

    // ── Events ────────────────────────────────────────────────────────────────
    event Registered(address indexed user, address indexed sponsor, address indexed binaryParent, bool placeLeft);
    event Activated(address indexed user, uint256 mvtMinted, uint256 grossMvt, uint256 levelAmt, uint256 binaryAmt, uint256 adminAmt);
    event LevelIncomePaid(address indexed to, address indexed from, uint8 level, uint256 amount);
    event LevelIncomeSkipped(address indexed upline, uint8 level, uint256 amount);
    event PlacementIncomePaid(address indexed to, address indexed from, uint8 level, uint256 amount);
    event MvtSold(address indexed user, uint256 mvtAmount, uint256 usdtNet, uint256 usdtToBtcPool, uint256 usdtToIncome, uint256 usdtToRebirth);
    event BtcPoolCredited(address indexed user, uint256 amount);
    event BtcPoolWithdrawn(address indexed user, uint256 amount);
    event UsdtWithdrawn(address indexed user, uint256 amount);
    event Reborn(address indexed mainAccount, address indexed subAccount, uint256 rebirthIndex);
    event Reactivated(address indexed user, uint256 pkgPrice, uint256 grossMvt, bool upgraded);
    event RankIncomePaid(address indexed to, address indexed from, uint8 rank, uint256 amount);
    event RankIncomeDistributed(uint256 totalPool, uint256 recipientCount);
    event RankUpdated(address indexed user, uint8 oldRank, uint8 newRank);
    event ProfileUpdated(address indexed user);
    event MvaultTokenUpdated(address newToken);
    event RegisteredAndActivatedFor(address indexed payer, address indexed newUser, address indexed sponsor, bool placeLeft);
    event AdminWithdraw(address indexed to, uint256 amount);
    event ReserveWithdraw(address indexed to, uint256 amount);
    event BoardEntered(address indexed user, uint256 boardLevel, uint256 usdtDeducted);
    event BoardRewardCredited(address indexed user, uint256 usdtAmount, uint256 boardLevel);
    event BoardHandlerUpdated(address indexed newHandler);
    event Staked(address indexed user, uint256 stakeIndex, uint256 usdtAmount, uint256 mvtMinted, bool isLocked);
    event Unstaked(address indexed user, uint256 stakeIndex, uint256 mvtReturned, uint256 usdtReceived, uint256 adminCapCut);
    event ConvertedToLocked(address indexed user, uint256 stakeIndex, uint256 lockedSince);
    event StakeLevelIncomePaid(address indexed to, address indexed from, uint8 level, uint256 mvtAmount);

    // ── Errors ────────────────────────────────────────────────────────────────
    error NotAuthorized();
    error AlreadyRegistered();
    error NotRegistered();
    error AlreadyActive();
    error NotActive();
    error InvalidSponsor();
    error PositionTaken();
    error InsufficientVirtualBalance();
    error InsufficientUsdtBalance();
    error InsufficientBtcPool();
    error InsufficientRebirthPool();
    error NoOpenBinarySlot();
    error ZeroAddress();
    error ZeroAmount();
    error TransferFailed();
    error InvalidPackage();
    error NotEligibleForRebirth();
    error IncomeNotExhausted();
    error CannotDowngradePackage();
    error BoardHandlerNotSet();
    error InsufficientBtcPoolForBoard();
    error NotBoardHandler();
    error ExceedsPool();
    error SubAccountAlreadyRegistered();
    error NotStakingModule();
    error InvalidAddress();
    error CannotSelfRegister();
    error CallerNotActive();
    error NoRebirthBalance();
    error UseRebirthInstead();

    // ─────────────────────────────────────────────────────────────────────────
    constructor(address _usdt, address _mvaultToken) Ownable(msg.sender) {
        if (_usdt == address(0) || _mvaultToken == address(0)) revert ZeroAddress();
        usdtToken   = IERC20(_usdt);
        mvaultToken = IMvaultToken(_mvaultToken);
        // Placement rates (bp/10000): L1=5% L2-3=2% L4=1% L5-12=0.5% L13-20=0.4% L21-28=0.3% L29-30=0.2%
        placementRates[0] = 500; placementRates[1] = 200; placementRates[2] = 200;
        placementRates[3] = 100;
        for (uint8 i = 4; i < 12; i++) placementRates[i] = 50;
        for (uint8 i = 12; i < 20; i++) placementRates[i] = 40;
        for (uint8 i = 20; i < 28; i++) placementRates[i] = 30;
        placementRates[28] = 20; placementRates[29] = 20;
        refsPerGroup = 1;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ADMIN SETTERS
    // ─────────────────────────────────────────────────────────────────────────

    function setMvaultToken(address _mvaultToken) external onlyOwner {
        if (_mvaultToken == address(0)) revert ZeroAddress();
        mvaultToken = IMvaultToken(_mvaultToken);
        emit MvaultTokenUpdated(_mvaultToken);
    }

    function setBoardHandler(address _boardHandler) external onlyOwner {
        if (_boardHandler == address(0)) revert ZeroAddress();
        boardHandler = IMvaultBoardMatrix(_boardHandler);
        emit BoardHandlerUpdated(_boardHandler);
    }

    function setStakingModule(address _staking) external onlyOwner {
        if (_staking == address(0)) revert ZeroAddress();
        stakingModule = IMvaultStaking(_staking);
    }

    // ── Manager role ──────────────────────────────────────────────────────────

    modifier onlyOwnerOrManager() {
        if (msg.sender != owner() && msg.sender != manager) revert NotAuthorized();
        _;
    }

    function setManager(address _manager) external onlyOwner {
        if (_manager == address(0)) revert ZeroAddress();
        manager = _manager;
    }

    function setCommunityWallet(address _wallet) external onlyOwner {
        if (_wallet == address(0)) revert ZeroAddress();
        communityWallet = _wallet;
    }

    function setPlacementRates(uint256[30] calldata _rates) external onlyOwner {
        for (uint8 i = 0; i < 30; i++) placementRates[i] = _rates[i];
    }

    function setRefsPerGroup(uint256 _refs) external onlyOwner {
        refsPerGroup = _refs;
    }

    function withdrawCommunityPool(address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        if (communityPool < amount) revert ExceedsPool();
        communityPool           -= amount;
        users[to].mvtBalance    += amount;
        users[to].totalReceived += amount;
    }

    modifier onlyStakingModule() {
        if (msg.sender != address(stakingModule)) revert NotStakingModule();
        _;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // BOARD MATRIX — ENTRY
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Use your BTC pool balance to enter the Board Matrix at Level 1.
     *         BTC pool fills automatically (10% of every MVT sell).
     *         Requires boardHandler to be set by admin.
     */
    function enterBoardPool() external nonReentrant {
        if (address(boardHandler) == address(0)) revert BoardHandlerNotSet();

        User storage u = users[msg.sender];
        if (!u.isActive) revert NotActive();

        uint256 price = boardHandler.getBoardPrice(1);
        if (u.btcPoolBalance < price) revert InsufficientBtcPoolForBoard();

        // Deduct from user's BTC pool
        u.btcPoolBalance -= price;

        // Transfer USDT to board handler
        bool ok = usdtToken.transfer(address(boardHandler), price);
        if (!ok) revert TransferFailed();

        // Register entry in board matrix
        boardEntryCount[msg.sender]++;
        boardHandler.enterBoard(msg.sender, 1);

        emit BoardEntered(msg.sender, 1, price);
        _recordTx(msg.sender, TX_BOARD_ENTRY, price, 1, address(0));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // BOARD MATRIX — REWARD CALLBACK (called by MvaultBoardMatrix)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Called by the board matrix contract when a board completes.
     *         USDT is transferred to this contract before this call,
     *         then credited to the user's withdrawable usdtBalance.
     */
    function creditBoardReward(address _user, uint256 _usdtAmount, uint256 _boardLevel) external nonReentrant {
        if (msg.sender != address(boardHandler)) revert NotBoardHandler();
        if (_user == address(0)) revert ZeroAddress();
        if (_usdtAmount == 0) revert ZeroAmount();

        users[_user].usdtBalance     += _usdtAmount;
        users[_user].totalUsdtEarned += _usdtAmount;
        totalBoardRewardsEarned[_user] += _usdtAmount;

        emit BoardRewardCredited(_user, _usdtAmount, _boardLevel);
        _recordTx(_user, TX_BOARD_REWARD, _usdtAmount, uint8(_boardLevel), address(0));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // STAKING MODULE — CALLBACKS (called by MvaultStaking)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Batch-credit virtual MVT income to a list of uplines.
     *         Called by MvaultStaking after computing the distribution off-chain.
     */
    function staking_batchCreditMvtIncome(
        address   staker,
        address[] calldata tos,
        uint8[]   calldata levels,
        uint256[] calldata amounts
    ) external onlyStakingModule {
        for (uint256 i = 0; i < tos.length; i++) {
            users[tos[i]].mvtBalance    += amounts[i];
            users[tos[i]].totalReceived += amounts[i];
            _recordTx(tos[i], TX_LEVEL_INCOME, amounts[i], levels[i], staker);
        }
    }

    /// @notice Called by MvaultStaking after executeStake completes.
    function staking_postStake(address user, uint256 usdtAmount, uint256 adminAmt)
        external onlyStakingModule
    {
        adminPool += adminAmt;
        _recordTx(user, TX_STAKE, usdtAmount, 0, address(0));
    }

    /// @notice Called by MvaultStaking after executeUnstake completes.
    function staking_postUnstake(address user, uint256 usdtToUser, uint256 adminCapCut)
        external onlyStakingModule
    {
        users[user].usdtBalance += usdtToUser;
        adminPool               += adminCapCut;
        _recordTx(user, TX_UNSTAKE, usdtToUser, 0, address(0));
    }

    function staking_getSponsorChain(address staker, uint8 depth)
        external view
        returns (address[] memory sponsors, bool[] memory actives)
    {
        sponsors = new address[](depth);
        actives  = new bool[](depth);
        address cur = users[staker].sponsor;
        for (uint8 i = 0; i < depth; i++) {
            if (cur == address(0)) break;
            sponsors[i] = cur;
            actives[i]  = users[cur].isActive;
            cur = users[cur].sponsor;
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // REGISTRATION
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Register a new user in the system.
     * @param sponsor       Your referrer. Pass address(0) only for the very first (root) user.
     * @param binaryParent  Node to be placed under. Pass address(0) to default to sponsor.
     * @param placeLeft     true = left side of binaryParent, false = right.
     */
    function register(
        address sponsor,
        address binaryParent,
        bool    placeLeft
    ) external {
        if (users[msg.sender].isRegistered) revert AlreadyRegistered();

        if (totalUsers == 0) {
            // Root / first user — no sponsor
            _createUser(msg.sender, address(0), address(0), false, address(0));
        } else {
            if (!users[sponsor].isRegistered) revert InvalidSponsor();

            // Start search from binaryParent if valid, otherwise from sponsor.
            // _findSlotOnSide walks the tree on-chain to find the deepest open slot
            // on the requested side — same logic used by rebirth().
            address startFrom = (binaryParent != address(0) && users[binaryParent].isRegistered)
                ? binaryParent
                : sponsor;

            (address parent, bool actualLeft) = _findSlotOnSide(startFrom, placeLeft);

            _createUser(msg.sender, sponsor, parent, actualLeft, address(0));

            if (actualLeft) users[parent].leftChild  = msg.sender;
            else            users[parent].rightChild = msg.sender;

            users[sponsor].directCount++;
            // Volume update deferred to _doActivate (when pkgPrice is known)
        }

        emit Registered(msg.sender, sponsor, binaryParent, placeLeft);
    }

    function _createUser(
        address u,
        address sponsor,
        address parent,
        bool    placeLeft,
        address main
    ) internal {
        users[u].isRegistered  = true;
        users[u].sponsor       = sponsor;
        users[u].binaryParent  = parent;
        users[u].placedLeft    = placeLeft;
        users[u].mainAccount   = main;
        users[u].joinedAt      = block.timestamp;
        allUsers.push(u);
        totalUsers++;
    }

    /**
     * @dev Walk up the binary tree and add `pkgPrice` (USDT) to the appropriate
     *      side volume counter on every ancestor.  Called at activation time so
     *      each activation contributes its real dollar value to binary volumes.
     */
    function _updateAncestorVolumes(address user, uint256 pkgPrice) internal {
        address cur    = users[user].binaryParent;
        bool    isLeft = users[user].placedLeft;

        while (cur != address(0)) {
            if (isLeft) users[cur].leftSubVolume  += pkgPrice;
            else        users[cur].rightSubVolume += pkgPrice;
            isLeft = users[cur].placedLeft;
            cur    = users[cur].binaryParent;
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ACTIVATION
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @dev Resolves package params from pkg index.
     *      pkg=1 → STARTER ($55 / $165 limit)
     *      pkg=2 → PRO     ($130 / $390 limit)
     */
    function _pkgParams(uint8 pkg) internal pure returns (uint256 price, uint256 incomeCap) {
        if (pkg == 1) return (PRICE_STARTER, INCOME_STARTER);
        if (pkg == 2) return (PRICE_PRO,     INCOME_PRO);
        revert InvalidPackage();
    }

    /**
     * @notice Pay USDT and activate. Choose your package:
     *         pkg=1 → STARTER $55  (income limit $165)
     *         pkg=2 → PRO     $130 (income limit $390)
     *         Caller must have pre-approved this contract for the chosen package price.
     */
    function activate(uint8 pkg) external nonReentrant {
        User storage u = users[msg.sender];
        if (!u.isRegistered) revert NotRegistered();
        if (u.isActive)      revert AlreadyActive();

        (uint256 price, uint256 incomeCap) = _pkgParams(pkg);
        bool ok = usdtToken.transferFrom(msg.sender, address(this), price);
        if (!ok) revert TransferFailed();

        _doActivate(msg.sender, price, incomeCap);
    }

    /**
     * @notice Activate using your in-contract USDT balance (usdtBalance).
     *         Useful if you have accumulated USDT from income/unstaking and want to
     *         self-activate without an external wallet transfer.
     *         pkg=1 → STARTER ($55)   pkg=2 → PRO ($130)
     */
    function activateFromBalance(uint8 pkg) external nonReentrant {
        User storage u = users[msg.sender];
        if (!u.isRegistered) revert NotRegistered();
        if (u.isActive)      revert AlreadyActive();

        (uint256 price, uint256 incomeCap) = _pkgParams(pkg);
        if (u.usdtBalance < price) revert InsufficientUsdtBalance();

        u.usdtBalance -= price;
        _doActivate(msg.sender, price, incomeCap);
    }

    /**
     * @notice Register a NEW wallet address and immediately activate it.
     *         Caller (msg.sender) becomes the direct sponsor of `newUser`.
     *         USDT is deducted from the caller's in-contract virtual usdtBalance.
     *         No external wallet approval needed — uses earned income already in the contract.
     *         pkg=1 → STARTER ($55)   pkg=2 → PRO ($130)
     */
    function registerAndActivateFor(
        address newUser,
        address binaryParent,
        bool    placeLeft,
        uint8   pkg
    ) external nonReentrant {
        if (newUser == address(0))           revert InvalidAddress();
        if (newUser == msg.sender)           revert CannotSelfRegister();
        if (!users[msg.sender].isRegistered) revert NotRegistered();
        if (!users[msg.sender].isActive)     revert CallerNotActive();
        if (users[newUser].isRegistered)     revert AlreadyRegistered();

        (uint256 price, uint256 incomeCap) = _pkgParams(pkg);
        if (users[msg.sender].usdtBalance < price) revert InsufficientUsdtBalance();

        // Determine binary parent (default = caller), then auto-find open slot on-chain
        address startFrom = (binaryParent != address(0) && users[binaryParent].isRegistered)
            ? binaryParent
            : msg.sender;

        (address parent, bool actualLeft) = _findSlotOnSide(startFrom, placeLeft);

        // Deduct from caller's virtual USDT balance (USDT already held by this contract)
        users[msg.sender].usdtBalance -= price;

        // Register newUser with caller as sponsor
        _createUser(newUser, msg.sender, parent, actualLeft, address(0));

        if (actualLeft) users[parent].leftChild  = newUser;
        else            users[parent].rightChild = newUser;

        users[msg.sender].directCount++;
        // Volume update deferred to _doActivate (when pkgPrice is known)

        emit Registered(newUser, msg.sender, parent, placeLeft);

        // Activate newUser (USDT already in contract)
        _doActivate(newUser, price, incomeCap);

        emit RegisteredAndActivatedFor(msg.sender, newUser, msg.sender, placeLeft);
    }

    /**
     * @dev Core activation logic.  USDT must already be in this contract before calling.
     *      pkgPrice   — amount paid ($55e18 or $130e18)
     *      incomeCap  — max income this cycle ($165e18 or $390e18)
     */
    function _doActivate(address user, uint256 pkgPrice, uint256 incomeCap) internal {
        // Snapshot buy price BEFORE minting (price rises after)
        uint256 buyPrice = mvaultToken.getBuyPrice();
        // Gross MVT = what pkgPrice buys at current price
        uint256 grossMvt = (pkgPrice * 1e18) / buyPrice;

        // Approve token contract and mint
        usdtToken.approve(address(mvaultToken), pkgPrice);
        uint256 before = mvaultToken.balanceOf(address(this));
        mvaultToken.addLiquidityAndMint(address(this), pkgPrice);
        uint256 minted = mvaultToken.balanceOf(address(this)) - before; // actual 90%

        // Split on GROSS basis: 30% level + 10% community + 20% placement + 20% admin + 10% rank
        uint256 levelAmt     = (grossMvt * LEVEL_ALLOC)     / 100;
        uint256 communityAmt = (grossMvt * COMMUNITY_ALLOC) / 100;
        uint256 placementAmt = (grossMvt * PLACEMENT_ALLOC) / 100;
        uint256 adminAmt     = (grossMvt * ADMIN_ALLOC)     / 100;
        uint256 rankAmt      = (grossMvt * RANK_ALLOC)      / 100;
        uint256 dust = grossMvt - levelAmt - communityAmt - placementAmt - adminAmt - rankAmt;

        communityPool += communityAmt;
        adminPool     += adminAmt + dust;

        users[user].isActive       = true;
        users[user].incomeLimit    = incomeCap;
        users[user].packagePrice   = pkgPrice;
        users[user].incomeLimitCap = incomeCap;

        _updateAncestorVolumes(user, pkgPrice);
        _updateTeamStats(user, pkgPrice);
        _distributeLevelIncome(user, grossMvt, levelAmt);
        _distributeRankIncome(user, grossMvt, rankAmt);
        _distributePlacementIncome(user, grossMvt, placementAmt);

        emit Activated(user, minted, grossMvt, levelAmt, communityAmt + placementAmt, adminAmt);
        _recordTx(user, TX_ACTIVATION, pkgPrice, 0, address(0));
    }

    /**
     * @dev Walks up 10 sponsor levels, credits qualifying uplines, unqualified → adminPool.
     */
    function _distributeLevelIncome(
        address from,
        uint256 grossMvt,
        uint256 levelAmt
    ) internal {
        address cur = users[from].sponsor;
        uint256 distributed = 0;

        for (uint8 lvl = 1; lvl <= 10 && cur != address(0); lvl++) {
            uint256 share = _levelShare(grossMvt, lvl);
            if (share == 0) { cur = users[cur].sponsor; continue; }

            distributed += share;

            bool qualified = users[cur].isActive
                && users[cur].directCount >= _directReq(lvl);

            if (qualified) {
                users[cur].mvtBalance    += share;
                users[cur].totalReceived += share;
                emit LevelIncomePaid(cur, from, lvl, share);
                _recordTx(cur, TX_LEVEL_INCOME, share, lvl, from);
            } else {
                adminPool += share;
                emit LevelIncomeSkipped(cur, lvl, share);
                _recordTx(cur, TX_LEVEL_MISSED, share, lvl, address(0));
            }

            cur = users[cur].sponsor;
        }

        // Dust from rounding → admin
        if (levelAmt > distributed) adminPool += levelAmt - distributed;
    }

    /** @dev Level share as % of gross MVT.  Rates sum to 30%. */
    function _levelShare(uint256 grossMvt, uint8 lvl) internal pure returns (uint256) {
        if (lvl == 1)  return (grossMvt * 20)  / 100;   // 20%
        if (lvl == 2)  return (grossMvt * 5)   / 100;   //  5%
        if (lvl == 3)  return (grossMvt * 2)   / 100;   //  2%
        if (lvl == 4)  return (grossMvt * 1)   / 100;   //  1%
        if (lvl == 5)  return (grossMvt * 5)   / 1000;  //  0.5%
        if (lvl == 6)  return (grossMvt * 5)   / 1000;  //  0.5%
        if (lvl == 7)  return (grossMvt * 3)   / 1000;  //  0.3%
        if (lvl == 8)  return (grossMvt * 3)   / 1000;  //  0.3%
        if (lvl == 9)  return (grossMvt * 2)   / 1000;  //  0.2%
        if (lvl == 10) return (grossMvt * 2)   / 1000;  //  0.2%
        return 0;
    }

    /**
     * @dev Immediately distributes the rank portion of a new activation up the
     *      sponsor chain.  Walks up to 50 hops looking for uplines with rank > 0.
     *
     *      Slot percentages (of grossMvt): M1=1%, M2=2%, M3=2%, M4=2%, M5=3%  (total 10%)
     *      A person with rank R fills all unfilled slots 1…R simultaneously.
     *      Unfilled slots → adminPool.  If all 5 slots are filled, admin gets 0.
     *
     *      Option B: if an upline has hit their incomeLimit the slot is NOT
     *      skipped — income goes to admin (consistent with level income).
     */
    function _distributeRankIncome(address from, uint256 grossMvt, uint256 rankAmt) internal {
        uint8   filled = 0;    // bitmask: bit k set ⟹ slot k is filled
        uint256 paid   = 0;
        address cur    = users[from].sponsor;

        for (uint256 depth = 0; depth < 50 && cur != address(0); depth++) {
            uint8 r = users[cur].rank;
            if (r > 5) r = 5;
            if (r > 0) {
                for (uint8 slot = 1; slot <= r; slot++) {
                    uint8 bit = uint8(1 << slot);
                    if (filled & bit == 0) {
                        filled |= bit;
                        uint256 slotAmt = _rankSlotAmt(slot, grossMvt);
                        users[cur].mvtBalance    += slotAmt;
                        users[cur].totalReceived += slotAmt;
                        paid += slotAmt;
                        emit RankIncomePaid(cur, from, slot, slotAmt);
                        _recordTx(cur, TX_RANK_INCOME, slotAmt, slot, from);
                    }
                }
            }
            if (filled == 0x3E) break;   // bits 1-5 all set → all slots filled
            cur = users[cur].sponsor;
        }

        if (rankAmt > paid) adminPool += rankAmt - paid;   // unfilled slots → admin
    }

    /// @dev Per-slot rank income amounts as % of grossMvt: 1%, 2%, 2%, 2%, 3%.
    function _rankSlotAmt(uint8 slot, uint256 grossMvt) internal pure returns (uint256) {
        if (slot == 1) return grossMvt / 100;           //  1%
        if (slot == 5) return (grossMvt * 3) / 100;    //  3%
        return (grossMvt * 2) / 100;                    //  2% (slots 2, 3, 4)
    }

    /** @dev Minimum directs needed to qualify at each level. */
    function _directReq(uint8 lvl) internal pure returns (uint256) {
        if (lvl == 1)  return 0;  // L1: no requirement — always paid to active sponsor
        if (lvl <= 4)  return 2;  // L2–L4: 2 direct sponsors
        return 5;                 // L5–L10: 5 direct sponsors
    }

    // ─────────────────────────────────────────────────────────────────────────
    // RANK SYSTEM
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @dev Walk up the sponsor tree from `from` and increment teamSalesUsdt on every ancestor.
     *      Also re-evaluates and updates the rank of each ancestor.
     *      Called on every activation / reactivation.
     */
    function _updateTeamStats(address from, uint256 pkgPrice) internal {
        address cur = users[from].sponsor;
        while (cur != address(0)) {
            users[cur].teamSalesUsdt += pkgPrice;
            cur = users[cur].sponsor;
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // SELL MVT
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Convert virtual MVT balance to USDT.
     *         USDT is held in the contract; call withdrawUsdt() to pull it.
     *
     *         Routing:
     *           ① If incomeLimit > 0  → USDT fills incomeLimit first  → usdtBalance
     *           ② Excess              → rebirthPool
     *           ③ If incomeLimit = 0  → all USDT goes to rebirthPool
     */
    function sellMvt(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        User storage u = users[msg.sender];
        if (!u.isActive)           revert NotRegistered();
        if (u.mvtBalance < amount) revert InsufficientVirtualBalance();

        u.mvtBalance -= amount;
        u.totalSold  += amount;

        // Burn MVT via token contract; receive USDT
        uint256 usdtBefore = usdtToken.balanceOf(address(this));
        mvaultToken.sell(amount);
        uint256 usdtReceived = usdtToken.balanceOf(address(this)) - usdtBefore;

        // ── Deduct BTC pool % (user-configurable 10–80%, default 10%) ───────
        uint256 _btcRate  = u.btcPoolRate != 0 ? u.btcPoolRate : BTC_POOL_RATE;
        uint256 btcCharge = (usdtReceived * _btcRate) / 100;
        uint256 netUsdt   = usdtReceived - btcCharge;

        u.btcPoolBalance += btcCharge;
        u.totalBtcEarned += btcCharge;
        emit BtcPoolCredited(msg.sender, btcCharge);
        _recordTx(msg.sender, TX_BTC_CREDITED, btcCharge, 0, address(0));

        // ── Route remaining 90% through income limit → rebirth pool ──────────
        uint256 toIncome  = 0;
        uint256 toRebirth = 0;

        if (u.incomeLimit > 0) {
            toIncome  = netUsdt > u.incomeLimit ? u.incomeLimit : netUsdt;
            toRebirth = netUsdt - toIncome;
            u.usdtBalance     += toIncome;
            u.incomeLimit     -= toIncome;
            u.totalUsdtEarned += toIncome;
        } else {
            toRebirth = netUsdt;
        }

        u.rebirthPool += toRebirth;

        emit MvtSold(msg.sender, amount, netUsdt, btcCharge, toIncome, toRebirth);
        _recordTx(msg.sender, TX_SELL_MVT, netUsdt, 0, address(0));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // WITHDRAW USDT
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Pull your accumulated USDT balance to your wallet.
     */
    function withdrawUsdt(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        User storage u = users[msg.sender];
        if (u.usdtBalance < amount) revert InsufficientUsdtBalance();

        u.usdtBalance -= amount;
        bool ok = usdtToken.transfer(msg.sender, amount);
        if (!ok) revert TransferFailed();

        emit UsdtWithdrawn(msg.sender, amount);
        _recordTx(msg.sender, TX_USDT_WITHDRAW, amount, 0, address(0));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // WITHDRAW BTC POOL
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Withdraw from your BTC pool balance.
     *         The USDT is sent to your wallet; the frontend/app handles BTC swap.
     *         10% of every sell accumulates here (same as backup contract pattern).
     */
    function withdrawBtcPool(uint256 amount) external nonReentrant {
        if (amount == 0) revert ZeroAmount();
        User storage u = users[msg.sender];
        if (u.btcPoolBalance < amount) revert InsufficientBtcPool();

        u.btcPoolBalance -= amount;
        bool ok = usdtToken.transfer(msg.sender, amount);
        if (!ok) revert TransferFailed();

        emit BtcPoolWithdrawn(msg.sender, amount);
        _recordTx(msg.sender, TX_BTC_WITHDRAW, amount, 0, address(0));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // REBIRTH
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @param subAccount  Fresh (unregistered) wallet address for the sub-account.
     * @param placeLeft   true = place sub-account on LEFT side of the open slot,
     *                    false = RIGHT side.  Tries directly under main account first;
     *                    if that side is taken, searches deeper on the chosen side (BFS).
     */
    function rebirth(address subAccount, bool placeLeft) external nonReentrant {
        if (subAccount == address(0)) revert ZeroAddress();

        User storage u = users[msg.sender];
        if (!u.isActive) revert NotActive();
        if (u.packagePrice != PRICE_PRO) revert NotEligibleForRebirth();
        if (u.rebirthPool < u.packagePrice) revert InsufficientRebirthPool();
        if (users[subAccount].isRegistered) revert SubAccountAlreadyRegistered();

        // ── 1. Deduct package price for sub-account activation ───────────────
        u.rebirthPool -= u.packagePrice;

        // ── 2. Reset income limit to full ─────────────────────────────────────
        u.incomeLimit = u.incomeLimitCap;

        // ── 3. Move remaining rebirth pool → main wallet through income limit ──
        // Credits the remainder to usdtBalance up to the newly reset income limit.
        // Excess beyond the income limit stays in rebirthPool (toward next rebirth).
        uint256 remaining = u.rebirthPool;
        if (remaining > 0) {
            uint256 toMain    = remaining > u.incomeLimit ? u.incomeLimit : remaining;
            u.rebirthPool    -= toMain;
            u.usdtBalance    += toMain;
            u.incomeLimit    -= toMain;
            u.totalUsdtEarned += toMain;
        }

        // ── 4. Register sub-account ───────────────────────────────────────────
        // Sponsor = main account's sponsor → sub-account's L1 income goes to
        // the person who originally referred the main account.
        address subSponsor = u.sponsor;

        // Place on the user's chosen side under main account.
        // If that slot is already taken, BFS deeper on the same preferred side.
        (address binParent, bool actualLeft) = _findSlotOnSide(msg.sender, placeLeft);

        _createUser(subAccount, subSponsor, binParent, actualLeft, msg.sender);

        if (actualLeft) users[binParent].leftChild  = subAccount;
        else            users[binParent].rightChild = subAccount;

        if (subSponsor != address(0)) users[subSponsor].directCount++;
        // Volume update handled in _doActivate below

        // ── 5 & 6. Activate sub-account (USDT already in contract) ───────────
        // Sub-account inherits the same package tier as the main account.
        _doActivate(subAccount, u.packagePrice, u.incomeLimitCap);

        u.rebirthCount++;

        emit Reborn(msg.sender, subAccount, u.rebirthCount);
        _recordTx(msg.sender, TX_REBIRTH, 0, 0, subAccount);
    }

    /**
     * @notice Claim a partial rebirth pool balance (< $130) back to USDT balance.
     *         If rebirthPool >= $130 the user must use rebirth() instead.
     *         This allows users to recover small overflow amounts that are not
     *         enough to trigger a full rebirth.
     */
    function claimRebirthBalance() external nonReentrant {
        User storage u = users[msg.sender];
        if (!u.isActive)               revert NotActive();
        if (u.rebirthPool == 0)              revert NoRebirthBalance();
        if (u.rebirthPool >= u.packagePrice) revert UseRebirthInstead();

        uint256 claim    = u.rebirthPool;
        u.rebirthPool    = 0;
        u.usdtBalance   += claim;
        u.totalUsdtEarned += claim;

        _recordTx(msg.sender, TX_REBIRTH_CLAIM, claim, 0, address(0));
    }

    // ─────────────────────────────────────────────────────────────────────────
    // REACTIVATION  (STARTER and PRO)
    //
    // When a user's incomeLimit reaches 0 they have two options:
    //   A) Reactivate at their current pkg price → income limit resets.
    //   B) Upgrade from STARTER → PRO by paying $130 → income limit resets
    //      to $390, packagePrice updated to PRO, rebirth becomes eligible.
    //
    // Rules:
    //   • Caller must be active and have incomeLimit == 0.
    //   • Cannot downgrade from PRO (pkg=2) to STARTER (pkg=1).
    //   • Same MVT minting and pool distributions as initial activation.
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Reactivate (or upgrade) by paying USDT from your wallet.
     *         pkg=1 → STARTER $55  (resets limit to $165, no rebirth)
     *         pkg=2 → PRO     $130 (resets limit to $390, rebirth eligible)
     *         Caller must pre-approve the contract for the chosen pkg price.
     */
    function reactivate(uint8 pkg) external nonReentrant {
        User storage u = users[msg.sender];
        if (!u.isActive)        revert NotActive();
        if (u.incomeLimit > 0)  revert IncomeNotExhausted();

        (uint256 price, uint256 incomeCap) = _pkgParams(pkg);
        if (u.packagePrice == PRICE_PRO && price < PRICE_PRO) revert CannotDowngradePackage();

        bool ok = usdtToken.transferFrom(msg.sender, address(this), price);
        if (!ok) revert TransferFailed();

        _doReactivate(msg.sender, price, incomeCap);
    }

    /**
     * @notice Reactivate (or upgrade) using your in-contract USDT balance.
     *         pkg=1 → STARTER $55   pkg=2 → PRO $130
     */
    function reactivateFromBalance(uint8 pkg) external nonReentrant {
        User storage u = users[msg.sender];
        if (!u.isActive)        revert NotActive();
        if (u.incomeLimit > 0)  revert IncomeNotExhausted();

        (uint256 price, uint256 incomeCap) = _pkgParams(pkg);
        if (u.packagePrice == PRICE_PRO && price < PRICE_PRO) revert CannotDowngradePackage();
        if (u.usdtBalance < price) revert InsufficientUsdtBalance();

        u.usdtBalance -= price;
        _doReactivate(msg.sender, price, incomeCap);
    }

    /**
     * @dev Core reactivation logic. Same MVT minting / distribution as activation.
     *      Updates packagePrice and incomeLimitCap to reflect any upgrade.
     */
    function _doReactivate(address user, uint256 pkgPrice, uint256 incomeCap) internal {
        bool upgraded = (users[user].packagePrice != pkgPrice);

        uint256 buyPrice = mvaultToken.getBuyPrice();
        uint256 grossMvt = (pkgPrice * 1e18) / buyPrice;

        usdtToken.approve(address(mvaultToken), pkgPrice);
        mvaultToken.addLiquidityAndMint(address(this), pkgPrice);

        uint256 levelAmt     = (grossMvt * LEVEL_ALLOC)     / 100;
        uint256 communityAmt = (grossMvt * COMMUNITY_ALLOC) / 100;
        uint256 placementAmt = (grossMvt * PLACEMENT_ALLOC) / 100;
        uint256 adminAmt     = (grossMvt * ADMIN_ALLOC)     / 100;
        uint256 rankAmt      = (grossMvt * RANK_ALLOC)      / 100;
        uint256 dust         = grossMvt - levelAmt - communityAmt - placementAmt - adminAmt - rankAmt;

        communityPool += communityAmt;
        adminPool     += adminAmt + dust;

        // Update package tier (handles both reactivation and upgrade)
        users[user].packagePrice   = pkgPrice;
        users[user].incomeLimitCap = incomeCap;
        users[user].incomeLimit    = incomeCap;

        _updateAncestorVolumes(user, pkgPrice);
        _updateTeamStats(user, pkgPrice);
        _distributeLevelIncome(user, grossMvt, levelAmt);
        _distributeRankIncome(user, grossMvt, rankAmt);
        _distributePlacementIncome(user, grossMvt, placementAmt);

        emit Reactivated(user, pkgPrice, grossMvt, upgraded);
        _recordTx(user, TX_REACTIVATION, pkgPrice, 0, address(0));
    }

    /**
     * @dev BFS from `start`, searching only on the preferred side first.
     *      If the preferred side's slot is open at `start`, returns immediately.
     *      Otherwise explores deeper on the preferred side; falls back to other side
     *      if the preferred subtree is completely full.
     */
    function _findSlotOnSide(address start, bool preferLeft)
        internal
        view
        returns (address parent, bool goLeft)
    {
        // Check direct slot under `start` first
        if (preferLeft  && users[start].leftChild  == address(0)) return (start, true);
        if (!preferLeft && users[start].rightChild == address(0)) return (start, false);

        // BFS deeper, honouring the preferred side
        address[] memory queue = new address[](totalUsers + 1);
        uint256 front = 0;
        uint256 back  = 0;

        // Seed with the preferred child subtree
        address preferredChild = preferLeft
            ? users[start].leftChild
            : users[start].rightChild;
        if (preferredChild != address(0)) queue[back++] = preferredChild;

        while (front < back) {
            address cur = queue[front++];
            if (users[cur].leftChild  == address(0)) return (cur, true);
            if (users[cur].rightChild == address(0)) return (cur, false);
            queue[back++] = users[cur].leftChild;
            queue[back++] = users[cur].rightChild;
        }

        // Fallback: check the other side of `start`
        if (!preferLeft && users[start].leftChild  == address(0)) return (start, true);
        if (preferLeft  && users[start].rightChild == address(0)) return (start, false);

        revert NoOpenBinarySlot();
    }

    // ─────────────────────────────────────────────────────────────────────────
    // PLACEMENT INCOME  (binary tree, 30 levels, paid instantly at activation)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @dev Walks up the binary parent chain up to 30 levels from `from`.
     *      Each level earns placementRates[lvl-1] basis points of grossMvt.
     *      Qualification: ceil(lvl/3) * refsPerGroup direct referrals needed.
     *      Unqualified or missing upline shares → adminPool.
     */
    function _distributePlacementIncome(address from, uint256 grossMvt, uint256 totalAmt) internal {
        address cur = users[from].binaryParent;
        uint256 distributed = 0;
        for (uint8 lvl = 1; lvl <= 30 && cur != address(0); lvl++) {
            uint256 share = (grossMvt * placementRates[lvl - 1]) / 10000;
            if (share > 0) {
                uint256 required = ((uint256(lvl) + 2) / 3) * refsPerGroup;
                if (users[cur].isActive && users[cur].directCount >= required) {
                    users[cur].mvtBalance    += share;
                    users[cur].totalReceived += share;
                    distributed += share;
                    emit PlacementIncomePaid(cur, from, lvl, share);
                    _recordTx(cur, TX_PLACEMENT_INCOME, share, lvl, from);
                } else {
                    adminPool += share;
                    if (users[cur].isRegistered) {
                        _recordTx(cur, TX_PLACEMENT_MISSED, share, lvl, from);
                    }
                }
            }
            cur = users[cur].binaryParent;
        }
        if (totalAmt > distributed) adminPool += totalAmt - distributed;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // ADMIN FUNCTIONS
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Move MVT from adminPool to a target address's virtual balance.
     */
    function withdrawAdminPool(address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        if (adminPool < amount) revert ExceedsPool();
        adminPool               -= amount;
        users[to].mvtBalance    += amount;
        users[to].totalReceived += amount;
        emit AdminWithdraw(to, amount);
    }

    /**
     * @notice Move MVT from reservePool to a target address's virtual balance.
     */
    function withdrawReservePool(address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        if (reservePool < amount) revert ExceedsPool();
        reservePool             -= amount;
        users[to].mvtBalance    += amount;
        users[to].totalReceived += amount;
        emit ReserveWithdraw(to, amount);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // STAKING — thin delegates to MvaultStaking module
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Stake USDT from the user's external wallet.
     *         Requires prior USDT approval for this contract.
     */
    function stake(uint256 usdtAmount, bool isLocked) external nonReentrant {
        if (!users[msg.sender].isRegistered) revert NotRegistered();
        if (!users[msg.sender].isActive) revert NotActive();
        bool ok = usdtToken.transferFrom(msg.sender, address(this), usdtAmount);
        if (!ok) revert TransferFailed();
        usdtToken.approve(address(stakingModule), usdtAmount);
        stakingModule.executeStake(msg.sender, usdtAmount, isLocked);
    }

    /**
     * @notice Stake using USDT held in this contract (from income, unstaking, or deposits).
     *         No external wallet approval needed — USDT is already in this contract.
     */
    function stakeFromBalance(uint256 usdtAmount, bool isLocked) external nonReentrant {
        if (!users[msg.sender].isRegistered) revert NotRegistered();
        if (!users[msg.sender].isActive) revert NotActive();
        if (users[msg.sender].usdtBalance < usdtAmount) revert InsufficientUsdtBalance();
        users[msg.sender].usdtBalance -= usdtAmount;
        usdtToken.approve(address(stakingModule), usdtAmount);
        stakingModule.executeStake(msg.sender, usdtAmount, isLocked);
    }

    /**
     * @notice Unstake a position (flexible or locked).
     */
    function unstake(uint256 stakeIndex) external nonReentrant {
        stakingModule.executeUnstake(msg.sender, stakeIndex);
    }

    /**
     * @notice Convert a flexible stake position to locked (starts 10-month lock).
     */
    function convertToLocked(uint256 stakeIndex) external {
        stakingModule.executeConvertToLocked(msg.sender, stakeIndex);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // VIEW FUNCTIONS
    // ─────────────────────────────────────────────────────────────────────────

    function getBtcPoolInfo(address u) external view returns (
        uint256 btcPoolBalance,
        uint256 totalBtcEarned
    ) {
        return (users[u].btcPoolBalance, users[u].totalBtcEarned);
    }

    /**
     * @notice Check whether a user can trigger a rebirth and how much is in their pool.
     */
    function canRebirth(address user) external view returns (bool eligible, uint256 poolBalance) {
        poolBalance = users[user].rebirthPool;
        eligible    = users[user].packagePrice > 0 && poolBalance >= users[user].packagePrice;
    }

    function getMvtPrice() external view returns (uint256 buyPrice, uint256 sellPrice) {
        buyPrice  = mvaultToken.getBuyPrice();
        sellPrice = mvaultToken.getSellPrice();
    }

    function getUserBoardStats(address _user) external view returns (
        uint256 entries,
        uint256 totalRewards
    ) {
        return (boardEntryCount[_user], totalBoardRewardsEarned[_user]);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // TRANSACTION HISTORY
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Return stored transaction records for `user`, newest-first.
     * @param user    Wallet address to query.
     * @param offset  Number of newest records to skip (0 = start from latest).
     * @param limit   Max records to return.
     * @return records Array of TxRecord structs.
     * @return total   Total number of records stored for this user.
     */
    function getTransactions(
        address user,
        uint256 offset,
        uint256 limit
    ) external view returns (TxRecord[] memory records, uint256 total) {
        TxRecord[] storage all = _txRecords[user];
        total = all.length;
        if (total == 0 || offset >= total) return (new TxRecord[](0), total);

        // newest-first: start from the last element and walk backwards
        uint256 available = total - offset;
        uint256 count     = limit < available ? limit : available;

        records = new TxRecord[](count);
        for (uint256 i = 0; i < count; i++) {
            records[i] = all[total - 1 - offset - i];
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // PROFILE
    // ─────────────────────────────────────────────────────────────────────────

    function setProfile(
        string calldata _displayName,
        string calldata _email,
        string calldata _phone,
        string calldata _country
    ) external {
        if (!users[msg.sender].isRegistered) revert NotRegistered();
        User storage u = users[msg.sender];
        u.displayName = _displayName;
        u.email       = _email;
        u.phone       = _phone;
        u.country     = _country;
        u.profileSet  = true;
        emit ProfileUpdated(msg.sender);
    }

    function setBtcPoolRate(uint8 _rate) external {
        require(users[msg.sender].isRegistered && _rate >= 10 && _rate <= 80, "E");
        users[msg.sender].btcPoolRate = _rate;
    }

    // ─────────────────────────────────────────────────────────────────────────
    // STAKING VIEW DELEGATES
    // ─────────────────────────────────────────────────────────────────────────

    function getStakeCount(address user) external view returns (uint256) {
        return stakingModule.getStakeCount(user);
    }

    function getStake(address user, uint256 index) external view returns (
        uint256 mvtAmount, uint256 usdtInvested, uint256 stakedAt, uint256 lockedSince, bool active
    ) {
        return stakingModule.getStake(user, index);
    }

    function getActiveStakes(address user) external view returns (
        uint256[] memory indices, uint256[] memory mvtAmounts,
        uint256[] memory usdtInvestedArr, uint256[] memory stakedAts, uint256[] memory lockedSinces
    ) {
        return stakingModule.getActiveStakes(user);
    }

    function MIN_STAKE_USDT()  external pure returns (uint256) { return 50 * 1e18; }
    function LOCK_DURATION()   external pure returns (uint256) { return 300 days; }
    function FLEX_CAP_MULT()   external pure returns (uint256) { return 2; }

    /**
     * @notice Get direct referrals of a user with pagination (newest first).
     */
    function getDirectReferralsPaginated(
        address _user,
        uint256 _offset,
        uint256 _limit
    ) external view returns (address[] memory referrals, uint256 total) {
        uint256 n = allUsers.length;
        // Count directs
        for (uint256 i = 0; i < n; i++) {
            if (users[allUsers[i]].sponsor == _user) total++;
        }
        if (total == 0 || _offset >= total) return (new address[](0), total);
        uint256 available = total - _offset;
        uint256 count = _limit < available ? _limit : available;
        referrals = new address[](count);
        uint256 found = 0;
        uint256 skip  = _offset;
        for (uint256 i = 0; i < n && found < count; i++) {
            if (users[allUsers[i]].sponsor == _user) {
                if (skip > 0) { skip--; continue; }
                referrals[found++] = allUsers[i];
            }
        }
    }

    /**
     * @notice MANAGER/OWNER: Batch-set user rank levels (0=unranked 1=M1…5=M5).
     *         Called by the off-chain distributor after evaluating qualifications.
     */
    function setUserRanks(address[] calldata addrs, uint8[] calldata ranks_) external onlyOwnerOrManager {
        require(addrs.length == ranks_.length);
        for (uint256 i; i < addrs.length; i++) {
            uint8 old = users[addrs[i]].rank;
            if (old != ranks_[i]) {
                users[addrs[i]].rank = ranks_[i];
                emit RankUpdated(addrs[i], old, ranks_[i]);
            }
        }
    }

    /**
     * @notice MANAGER/OWNER: Flush any legacy rankPool balance → adminPool.
     *         Rank income is now distributed on-chain at activation time via
     *         _distributeRankIncome(), so rankPool should always be 0.
     *         This function exists only as a safety drain for any accumulated
     *         balance from before the on-chain distribution upgrade.
     */
    function drainRankPool() external onlyOwnerOrManager {
        if (rankPool == 0) revert ExceedsPool();
        uint256 pool = rankPool;
        rankPool = 0;
        adminPool += pool;
        emit RankIncomeDistributed(pool, 0);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // INTERNAL HELPERS
    // ─────────────────────────────────────────────────────────────────────────

    function _minOf(uint256 a, uint256 b) internal pure returns (uint256) {
        return a < b ? a : b;
    }
}

contracts/MvaultDistributor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

// ─────────────────────────────────────────────
// Minimal interface — only the callbacks we need
// ─────────────────────────────────────────────
interface IMvaultMain {
    function distributor_lockPool()                                                                  external returns (uint256 pool);
    function distributor_creditUser(address user, uint256 mvtAmount, uint256 newMatchedVol, uint256 newPowerLegPts) external;
}

/**
 * @title  MvaultDistributor
 * @notice Trustless Merkle-proof binary / power-leg distribution for M-Vault.
 *
 *         Flow:
 *           1. Admin computes shares off-chain, builds a Merkle tree
 *              where each leaf encodes (cycle, user, binaryShare, powerLegShare,
 *              newMatchedVol, newPowerLegPts).
 *           2. Admin calls commitDistribution(root, totalPool) — locks only the
 *              NEW pool for this cycle from MvaultContract.binaryPool.
 *           3. Each user calls claimDistribution(..., proof) at ANY time — no expiry.
 *              The contract verifies the proof and credits their MVT balance.
 *
 *         Carry-forward design:
 *           • If a user skips claiming cycle N, cycle N+1 naturally includes their
 *             unclaimed pairs because matchedVolume on-chain is only updated on claim.
 *           • Each cycle is independently claimable; there is no expiry.
 *           • Users can claim multiple cycles back-to-back without restriction.
 *
 *         Security guarantees:
 *           • Admin CANNOT alter individual payouts once the root is committed.
 *           • Total distributed can NEVER exceed the committed pool (on-chain sum check).
 *           • Users verify their own allocation independently via the Merkle proof.
 *           • No double-claiming: hasClaimed[cycle][address] flag.
 */
contract MvaultDistributor is Ownable, ReentrancyGuard {

    IMvaultMain public mvault;

    uint256 public currentCycle;

    struct Distribution {
        bytes32 root;
        uint256 totalPool;      // MVT locked this cycle — upper bound for all claims in this cycle
        uint256 claimedTotal;   // running sum of claimed amounts (≤ totalPool always)
        uint256 committedAt;    // block.timestamp when committed (informational)
    }

    mapping(uint256 => Distribution)              public distributions;
    mapping(uint256 => mapping(address => bool))  public hasClaimed;

    // ── Errors ────────────────────────────────────────────────────────────────
    error AlreadyClaimed();
    error InvalidProof();
    error MvaultNotSet();
    error ZeroRoot();
    error ZeroPool();
    error PoolMismatch();

    // ── Events ────────────────────────────────────────────────────────────────
    event DistributionCommitted(uint256 indexed cycle, bytes32 root, uint256 totalPool);
    event DistributionClaimed(address indexed user, uint256 indexed cycle, uint256 mvtAmount);
    event MvaultUpdated(address newMvault);

    // ─────────────────────────────────────────────────────────────────────────
    constructor(address _mvault) Ownable(msg.sender) {
        if (_mvault == address(0)) revert MvaultNotSet();
        mvault = IMvaultMain(_mvault);
    }

    function setMvault(address _mvault) external onlyOwner {
        if (_mvault == address(0)) revert MvaultNotSet();
        mvault = IMvaultMain(_mvault);
        emit MvaultUpdated(_mvault);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // COMMIT (admin — once per distribution cycle)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Commit a new distribution cycle.
     *         Locks the FULL current binaryPool from MvaultContract into this cycle.
     *         `totalPool` must equal the declared sum of all leaf (binaryShare + powerLegShare)
     *         for NEW income this cycle. Any pool excess (rounding dust) stays in the locked
     *         balance to cover future cycles.
     *
     * @param root       Merkle root (StandardMerkleTree, double-keccak leaf encoding)
     * @param totalPool  Sum of all (binaryShare + powerLegShare) in the tree for this cycle
     */
    function commitDistribution(bytes32 root, uint256 totalPool) external onlyOwner {
        if (root      == bytes32(0)) revert ZeroRoot();
        if (totalPool == 0)          revert ZeroPool();

        // Drain binaryPool from MvaultContract
        uint256 locked = mvault.distributor_lockPool();
        if (locked < totalPool) revert PoolMismatch();

        currentCycle++;
        distributions[currentCycle] = Distribution({
            root:         root,
            totalPool:    locked,   // store full locked amount (≥ totalPool, dust stays in contract)
            claimedTotal: 0,
            committedAt:  block.timestamp
        });

        emit DistributionCommitted(currentCycle, root, totalPool);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // CLAIM (users — at ANY time, no expiry)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Claim your binary + power-leg income for a given cycle.
     *         Can be called at any time — there is no expiry or time limit.
     *
     *         Caller must supply the exact values from the Merkle tree leaf
     *         (available from backend API: GET /api/distribution/proofs/:address).
     *
     * @param cycle          Distribution cycle number
     * @param binaryShare    Caller's binary income share (MVT wei)
     * @param powerLegShare  Caller's power-leg share (MVT wei)
     * @param newMatchedVol  Caller's updated matched-volume watermark after this cycle
     * @param newPowerLegPts Caller's updated power-leg points after this cycle
     * @param proof          Merkle proof (array of bytes32 siblings)
     */
    function claimDistribution(
        uint256   cycle,
        uint256   binaryShare,
        uint256   powerLegShare,
        uint256   newMatchedVol,
        uint256   newPowerLegPts,
        bytes32[] calldata proof
    ) external nonReentrant {
        if (hasClaimed[cycle][msg.sender]) revert AlreadyClaimed();

        Distribution storage d = distributions[cycle];

        // Reconstruct leaf using the same encoding as StandardMerkleTree.of()
        bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(
            cycle, msg.sender, binaryShare, powerLegShare, newMatchedVol, newPowerLegPts
        ))));

        if (!MerkleProof.verify(proof, d.root, leaf)) revert InvalidProof();

        // On-chain safety: cumulative claims can never exceed this cycle's locked pool
        uint256 total = binaryShare + powerLegShare;
        d.claimedTotal += total;
        require(d.claimedTotal <= d.totalPool, "Exceeds pool");

        hasClaimed[cycle][msg.sender] = true;

        // Credit user's MVT balance and update binary watermark in MvaultContract
        mvault.distributor_creditUser(msg.sender, total, newMatchedVol, newPowerLegPts);

        emit DistributionClaimed(msg.sender, cycle, total);
    }

    // ─────────────────────────────────────────────────────────────────────────
    // BATCH CLAIM (users — all unclaimed cycles in one transaction)
    // ─────────────────────────────────────────────────────────────────────────

    /**
     * @notice Claim multiple cycles in a single transaction — one MetaMask popup.
     *         Already-claimed cycles are silently skipped (no revert).
     *         Arrays must all be the same length and ordered ascending by cycle
     *         so that newMatchedVol / newPowerLegPts are applied in the correct order.
     *
     * @param cycles          Array of cycle numbers to claim
     * @param binaryShares    Corresponding binary income shares (MVT wei)
     * @param powerLegShares  Corresponding power-leg shares (MVT wei)
     * @param newMatchedVols  Corresponding updated matched-volume watermarks
     * @param newPowerLegPts  Corresponding updated power-leg points
     * @param proofs          Corresponding Merkle proofs (2-D array)
     */
    function batchClaim(
        uint256[]   calldata cycles,
        uint256[]   calldata binaryShares,
        uint256[]   calldata powerLegShares,
        uint256[]   calldata newMatchedVols,
        uint256[]   calldata newPowerLegPts,
        bytes32[][] calldata proofs
    ) external nonReentrant {
        uint256 len = cycles.length;
        require(
            binaryShares.length == len &&
            powerLegShares.length == len &&
            newMatchedVols.length == len &&
            newPowerLegPts.length == len &&
            proofs.length == len,
            "Length mismatch"
        );

        for (uint256 i = 0; i < len; i++) {
            uint256 cycle = cycles[i];

            // Skip already-claimed cycles silently
            if (hasClaimed[cycle][msg.sender]) continue;

            Distribution storage d = distributions[cycle];

            bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(
                cycle, msg.sender,
                binaryShares[i], powerLegShares[i],
                newMatchedVols[i], newPowerLegPts[i]
            ))));

            if (!MerkleProof.verify(proofs[i], d.root, leaf)) revert InvalidProof();

            uint256 total = binaryShares[i] + powerLegShares[i];
            d.claimedTotal += total;
            require(d.claimedTotal <= d.totalPool, "Exceeds pool");

            hasClaimed[cycle][msg.sender] = true;

            mvault.distributor_creditUser(
                msg.sender, total, newMatchedVols[i], newPowerLegPts[i]
            );

            emit DistributionClaimed(msg.sender, cycle, total);
        }
    }

    // ─────────────────────────────────────────────────────────────────────────
    // VIEW
    // ─────────────────────────────────────────────────────────────────────────

    function getDistribution(uint256 cycle) external view returns (
        bytes32 root, uint256 totalPool, uint256 claimedTotal, uint256 committedAt
    ) {
        Distribution storage d = distributions[cycle];
        return (d.root, d.totalPool, d.claimedTotal, d.committedAt);
    }
}

contracts/MvaultStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface IMvaultToken {
    function addLiquidityAndMint(address to, uint256 usdtAmount) external;
    function sell(uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

interface IMvaultMain {
    function staking_batchCreditMvtIncome(
        address staker,
        address[] calldata tos,
        uint8[]   calldata levels,
        uint256[] calldata amounts
    ) external;
    function staking_postStake(address user, uint256 usdtAmount, uint256 adminAmt) external;
    function staking_postUnstake(address user, uint256 usdtToUser, uint256 adminCapCut) external;
    function staking_getSponsorChain(address staker, uint8 depth)
        external view returns (address[] memory sponsors, bool[] memory actives);
}

contract MvaultStaking is Ownable, ReentrancyGuard {

    IERC20        public immutable usdtToken;
    IMvaultToken  public immutable mvaultToken;
    IMvaultMain   public           mvaultMain;

    uint256 public constant MIN_STAKE_USDT = 50  * 1e18;
    uint256 public constant LOCK_DURATION  = 300 days;
    uint256 public constant FLEX_CAP_MULT  = 2;

    uint8 internal constant TX_LEVEL_INCOME = 1;
    uint8 internal constant TX_STAKE        = 12;
    uint8 internal constant TX_UNSTAKE      = 13;

    struct StakePosition {
        uint256 mvtAmount;
        uint256 usdtInvested;
        uint256 stakedAt;
        uint256 lockedSince;
        bool    active;
    }

    mapping(address => StakePosition[]) private _stakes;

    event Staked(address indexed user, uint256 stakeIndex, uint256 usdtAmount, uint256 mvtMinted, bool isLocked);
    event Unstaked(address indexed user, uint256 stakeIndex, uint256 mvtReturned, uint256 usdtReceived, uint256 adminCapCut);
    event ConvertedToLocked(address indexed user, uint256 stakeIndex, uint256 lockedSince);
    event StakeLevelIncomePaid(address indexed to, address indexed from, uint8 level, uint256 mvtAmount);

    error BelowMinStake();
    error AlreadyUnstaked();
    error AlreadyLocked();
    error StillLocked();
    error NoMvtMinted();
    error InvalidIndex();
    error NotMvaultContract();

    modifier onlyMvaultMain() {
        if (msg.sender != address(mvaultMain)) revert NotMvaultContract();
        _;
    }

    constructor(address _owner, address _mvaultMain, address _usdt, address _mvaultToken)
        Ownable(_owner)
    {
        mvaultMain  = IMvaultMain(_mvaultMain);
        usdtToken   = IERC20(_usdt);
        mvaultToken = IMvaultToken(_mvaultToken);
    }

    function setMvaultMain(address _main) external onlyOwner {
        mvaultMain = IMvaultMain(_main);
    }

    /**
     * @notice Called by MvaultContract.stake() and MvaultContract.stakeFromBalance().
     *         USDT is already in MvaultContract and approved for this contract.
     */
    function executeStake(address user, uint256 amount, bool isLocked)
        external onlyMvaultMain nonReentrant
    {
        if (amount < MIN_STAKE_USDT) revert BelowMinStake();

        // Pull USDT from MvaultContract
        usdtToken.transferFrom(address(mvaultMain), address(this), amount);

        // Mint MVT via bonding curve (mints 90% of theoretical = grossMvt)
        usdtToken.approve(address(mvaultToken), amount);
        uint256 balBefore = mvaultToken.balanceOf(address(this));
        mvaultToken.addLiquidityAndMint(address(this), amount);
        uint256 grossMvt = mvaultToken.balanceOf(address(this)) - balBefore;
        if (grossMvt == 0) revert NoMvtMinted();

        // 20% → 10 upline levels; compute distribution locally, then batch-credit via callback
        uint256[10] memory levelRates = [uint256(100), 50, 20, 10, 5, 5, 3, 3, 2, 2];
        (address[] memory sponsors, bool[] memory actives) =
            mvaultMain.staking_getSponsorChain(user, 10);

        address[]  memory creditTos     = new address[](10);
        uint8[]    memory creditLevels  = new uint8[](10);
        uint256[]  memory creditAmounts = new uint256[](10);
        uint256 creditCount      = 0;
        uint256 levelDistributed = 0;
        uint256 levelToAdmin     = 0;

        for (uint8 i = 0; i < 10; i++) {
            uint256 share = grossMvt * levelRates[i] / 1000;
            if (share == 0) continue;
            if (i >= sponsors.length || sponsors[i] == address(0) || !actives[i]) {
                levelToAdmin += share;
            } else {
                creditTos[creditCount]     = sponsors[i];
                creditLevels[creditCount]  = i + 1;
                creditAmounts[creditCount] = share;
                creditCount++;
                levelDistributed += share;
                emit StakeLevelIncomePaid(sponsors[i], user, i + 1, share);
            }
        }

        if (creditCount > 0) {
            // Trim arrays to actual length
            assembly { mstore(creditTos, creditCount) mstore(creditLevels, creditCount) mstore(creditAmounts, creditCount) }
            mvaultMain.staking_batchCreditMvtIncome(user, creditTos, creditLevels, creditAmounts);
        }

        // 10% → adminPool + unqualified level shares (5% base + 5% from removed liquidity slice)
        uint256 adminAmt = grossMvt * 10 / 100;

        // 70% → user stake (90% mint + sell rate provides natural price support; no separate liquidity slice needed)
        uint256 stakedMvt = grossMvt - levelDistributed - levelToAdmin - adminAmt;
        if (stakedMvt == 0) revert NoMvtMinted();

        // Transfer all non-staked MVT to MvaultContract so virtual mvtBalance + adminPool credits
        // are backed by real ERC20 tokens that MvaultContract can burn when users call sellMvt().
        // Only stakedMvt stays here (burned on unstake via mvaultToken.sell()).
        uint256 toTransfer = levelDistributed + levelToAdmin + adminAmt;
        if (toTransfer > 0) {
            IERC20(address(mvaultToken)).transfer(address(mvaultMain), toTransfer);
        }

        uint256 stakeIndex = _stakes[user].length;
        _stakes[user].push(StakePosition({
            mvtAmount:    stakedMvt,
            usdtInvested: amount,
            stakedAt:     block.timestamp,
            lockedSince:  isLocked ? block.timestamp : 0,
            active:       true
        }));

        mvaultMain.staking_postStake(user, amount, adminAmt + levelToAdmin);
        emit Staked(user, stakeIndex, amount, stakedMvt, isLocked);
    }

    /**
     * @notice Called by MvaultContract.unstake().
     */
    function executeUnstake(address user, uint256 stakeIndex)
        external onlyMvaultMain nonReentrant
    {
        if (stakeIndex >= _stakes[user].length) revert InvalidIndex();
        StakePosition storage pos = _stakes[user][stakeIndex];
        if (!pos.active) revert AlreadyUnstaked();

        bool isLocked = pos.lockedSince > 0;
        if (isLocked && block.timestamp < pos.lockedSince + LOCK_DURATION) revert StillLocked();

        pos.active = false;
        uint256 totalMvt = pos.mvtAmount;
        uint256 usdtCap  = pos.usdtInvested * FLEX_CAP_MULT;
        uint256 toSell   = totalMvt;

        {
            uint8 depth = isLocked ? 5 : 1;
            (address[] memory sponsors, bool[] memory actives) =
                mvaultMain.staking_getSponsorChain(user, depth);

            address[] memory tos     = new address[](depth);
            uint8[]   memory lvls    = new uint8[](depth);
            uint256[] memory amts    = new uint256[](depth);
            uint256 cnt = 0;

            uint8[5] memory rates = isLocked ? [uint8(5), 2, 1, 1, 1] : [uint8(5), 0, 0, 0, 0];

            for (uint8 i = 0; i < uint8(sponsors.length); i++) {
                if (rates[i] == 0) break;
                if (!actives[i] || sponsors[i] == address(0)) continue;
                uint256 share = (totalMvt * rates[i]) / 100;
                if (share == 0) continue;
                tos[cnt]  = sponsors[i];
                lvls[cnt] = i + 1;
                amts[cnt] = share;
                cnt++;
                toSell -= share;
                emit StakeLevelIncomePaid(sponsors[i], user, i + 1, share);
            }
            if (cnt > 0) {
                assembly { mstore(tos, cnt) mstore(lvls, cnt) mstore(amts, cnt) }
                mvaultMain.staking_batchCreditMvtIncome(user, tos, lvls, amts);
            }
        }

        // Sell remaining MVT → USDT lands in this contract
        uint256 usdtBefore = usdtToken.balanceOf(address(this));
        mvaultToken.sell(toSell);
        uint256 usdtGross  = usdtToken.balanceOf(address(this)) - usdtBefore;

        uint256 usdtToUser  = usdtGross;
        uint256 adminCapCut = 0;

        if (!isLocked && usdtGross > usdtCap) {
            adminCapCut = usdtGross - usdtCap;
            usdtToUser  = usdtCap;
        }

        // Transfer all USDT to MvaultContract; callback credits user and records tx
        if (usdtGross > 0) {
            usdtToken.transfer(address(mvaultMain), usdtGross);
        }
        mvaultMain.staking_postUnstake(user, usdtToUser, adminCapCut);
        emit Unstaked(user, stakeIndex, totalMvt, usdtToUser, adminCapCut);
    }

    /**
     * @notice Called by MvaultContract.convertToLocked().
     */
    function executeConvertToLocked(address user, uint256 stakeIndex)
        external onlyMvaultMain
    {
        if (stakeIndex >= _stakes[user].length) revert InvalidIndex();
        StakePosition storage pos = _stakes[user][stakeIndex];
        if (!pos.active) revert AlreadyUnstaked();
        if (pos.lockedSince != 0) revert AlreadyLocked();

        pos.lockedSince = block.timestamp;
        emit ConvertedToLocked(user, stakeIndex, block.timestamp);
    }

    // ── View functions ──────────────────────────────────────────────────────────

    function getStakeCount(address user) external view returns (uint256) {
        return _stakes[user].length;
    }

    function getStake(address user, uint256 index)
        external view returns (
            uint256 mvtAmount,
            uint256 usdtInvested,
            uint256 stakedAt,
            uint256 lockedSince,
            bool    active
        )
    {
        StakePosition storage p = _stakes[user][index];
        return (p.mvtAmount, p.usdtInvested, p.stakedAt, p.lockedSince, p.active);
    }

    function getActiveStakes(address user) external view returns (
        uint256[] memory indices,
        uint256[] memory mvtAmounts,
        uint256[] memory usdtInvestedArr,
        uint256[] memory stakedAts,
        uint256[] memory lockedSinces
    ) {
        StakePosition[] storage positions = _stakes[user];
        uint256 count = 0;
        for (uint256 i = 0; i < positions.length; i++) {
            if (positions[i].active) count++;
        }
        indices        = new uint256[](count);
        mvtAmounts     = new uint256[](count);
        usdtInvestedArr = new uint256[](count);
        stakedAts      = new uint256[](count);
        lockedSinces   = new uint256[](count);
        uint256 j = 0;
        for (uint256 i = 0; i < positions.length; i++) {
            if (!positions[i].active) continue;
            indices[j]         = i;
            mvtAmounts[j]      = positions[i].mvtAmount;
            usdtInvestedArr[j] = positions[i].usdtInvested;
            stakedAts[j]       = positions[i].stakedAt;
            lockedSinces[j]    = positions[i].lockedSince;
            j++;
        }
    }
}

contracts/MvaultToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title MvaultToken
 * @notice M-Vault bonding curve token (MVT)
 * @dev Buy price is calculated BEFORE adding liquidity to prevent front-running
 *      - Buy: send USDT → receive 90% of calculated MVT tokens
 *      - Sell: burn MVT tokens → receive 90% of sell price in USDT
 *      - Price = totalLiquidity / totalSupply (rises on buy, falls on sell)
 *      - Only the designated MvaultContract can trigger minting
 */
contract MvaultToken is ERC20, Ownable, ReentrancyGuard {

    IERC20 public immutable usdtToken;
    address public mvaultContract;
    address public stakingModule;

    uint256 public totalLiquidity;
    uint256 public totalMinted;
    uint256 public totalBurned;

    uint256 public constant INITIAL_PRICE  = 0.01 ether;
    uint256 public constant MINT_PERCENTAGE = 90;
    uint256 public constant SELL_PERCENTAGE = 90;

    mapping(address => uint256) public totalReceivedByUser;
    mapping(address => uint256) public totalBurnedByUser;

    struct TokenTransfer {
        uint256 usdtAmount;
        uint256 mvtAmount;
        uint256 timestamp;
        uint8   transferType;
    }

    mapping(address => TokenTransfer[]) private userTransferHistory;

    event PriceUpdated(uint256 newBuyPrice, uint256 newSellPrice);
    event TokensMinted(address indexed to, uint256 usdtAmount, uint256 mvtAmount);
    event TokensBurned(address indexed from, uint256 mvtAmount, uint256 usdtAmount);
    event MvaultContractUpdated(address indexed oldContract, address indexed newContract);

    error ZeroAddress();
    error ZeroAmount();
    error OnlyMvault();
    error InsufficientBalance();
    error InsufficientLiquidity();
    error TransferFailed();

    constructor(address _usdt) ERC20("Mvault Token", "MVT") Ownable(msg.sender) {
        if (_usdt == address(0)) revert ZeroAddress();
        usdtToken = IERC20(_usdt);
    }

    modifier onlyMvault() {
        if (msg.sender != mvaultContract && msg.sender != stakingModule) revert OnlyMvault();
        _;
    }

    function setMvaultContract(address _contract) external onlyOwner {
        if (_contract == address(0)) revert ZeroAddress();
        address old = mvaultContract;
        mvaultContract = _contract;
        emit MvaultContractUpdated(old, _contract);
    }

    function setStakingModule(address _staking) external onlyOwner {
        if (_staking == address(0)) revert ZeroAddress();
        stakingModule = _staking;
    }

    /**
     * @notice Mint MVT tokens by depositing USDT.
     *         Only callable by the authorised MvaultContract.
     * @param _to          Recipient of the minted tokens
     * @param _usdtAmount  USDT amount (must be pre-approved to this contract)
     */
    function addLiquidityAndMint(address _to, uint256 _usdtAmount)
        external
        onlyMvault
        nonReentrant
    {
        if (_to == address(0)) revert ZeroAddress();
        if (_usdtAmount == 0) revert ZeroAmount();

        uint256 buyPrice = getBuyPrice();

        bool success = usdtToken.transferFrom(msg.sender, address(this), _usdtAmount);
        if (!success) revert TransferFailed();

        totalLiquidity += _usdtAmount;

        uint256 tokensToMint = (_usdtAmount * 1e18) / buyPrice;
        uint256 mintAmount   = (tokensToMint * MINT_PERCENTAGE) / 100;

        totalMinted += mintAmount;
        totalReceivedByUser[_to] += mintAmount;

        userTransferHistory[_to].push(TokenTransfer({
            usdtAmount:   _usdtAmount,
            mvtAmount:    mintAmount,
            timestamp:    block.timestamp,
            transferType: 0
        }));

        _mint(_to, mintAmount);

        emit TokensMinted(_to, _usdtAmount, mintAmount);
        emit PriceUpdated(getBuyPrice(), getSellPrice());
    }

    /**
     * @notice Sell (burn) MVT tokens and receive USDT.
     *         Callable by any token holder.
     * @param _amount  Number of MVT tokens to sell
     */
    function sell(uint256 _amount) external nonReentrant {
        if (_amount == 0) revert ZeroAmount();
        if (balanceOf(msg.sender) < _amount) revert InsufficientBalance();

        uint256 usdtOut = (_amount * getSellPrice()) / 1e18;
        if (totalLiquidity < usdtOut) revert InsufficientLiquidity();

        totalBurned += _amount;
        totalBurnedByUser[msg.sender] += _amount;
        totalLiquidity -= usdtOut;

        userTransferHistory[msg.sender].push(TokenTransfer({
            usdtAmount:   usdtOut,
            mvtAmount:    _amount,
            timestamp:    block.timestamp,
            transferType: 2
        }));

        _burn(msg.sender, _amount);

        bool success = usdtToken.transfer(msg.sender, usdtOut);
        if (!success) revert TransferFailed();

        emit TokensBurned(msg.sender, _amount, usdtOut);
        emit PriceUpdated(getBuyPrice(), getSellPrice());
    }

    function getBuyPrice() public view returns (uint256) {
        if (totalSupply() == 0) return INITIAL_PRICE;
        return (totalLiquidity * 1e18) / totalSupply();
    }

    function getSellPrice() public view returns (uint256) {
        return (getBuyPrice() * SELL_PERCENTAGE) / 100;
    }

    function decimals() public pure override returns (uint8) {
        return 18;
    }

    function getTotalLiquidity() external view returns (uint256) {
        return totalLiquidity;
    }

    function getTotalAvailableTokens() external view returns (uint256) {
        return totalSupply();
    }

    function getTotalBurnedTokens() external view returns (uint256) {
        return totalBurned;
    }

    function getTotalMintedTokens() external view returns (uint256) {
        return totalMinted;
    }

    function getTotalReceivedByUser(address user) external view returns (uint256) {
        return totalReceivedByUser[user];
    }

    function getTotalBurnedByUser(address user) external view returns (uint256) {
        return totalBurnedByUser[user];
    }

    function getUserTransferCount(address user) external view returns (uint256) {
        return userTransferHistory[user].length;
    }

    function getUserTransferHistory(
        address user,
        uint256 start,
        uint256 limit
    ) external view returns (
        uint256[] memory usdtAmounts,
        uint256[] memory mvtAmounts,
        uint256[] memory timestamps,
        uint8[]   memory types
    ) {
        TokenTransfer[] storage history = userTransferHistory[user];
        uint256 end = start + limit;
        if (end > history.length) end = history.length;
        if (start >= history.length) {
            return (new uint256[](0), new uint256[](0), new uint256[](0), new uint8[](0));
        }
        uint256 size = end - start;
        usdtAmounts = new uint256[](size);
        mvtAmounts  = new uint256[](size);
        timestamps  = new uint256[](size);
        types       = new uint8[](size);
        for (uint256 i = 0; i < size; i++) {
            TokenTransfer storage t = history[start + i];
            usdtAmounts[i] = t.usdtAmount;
            mvtAmounts[i]  = t.mvtAmount;
            timestamps[i]  = t.timestamp;
            types[i]       = t.transferType;
        }
    }

    function getRecentTransfers(
        address user,
        uint256 count
    ) external view returns (
        uint256[] memory usdtAmounts,
        uint256[] memory mvtAmounts,
        uint256[] memory timestamps,
        uint8[]   memory types
    ) {
        TokenTransfer[] storage history = userTransferHistory[user];
        uint256 len = history.length;
        if (len == 0) {
            return (new uint256[](0), new uint256[](0), new uint256[](0), new uint8[](0));
        }
        uint256 size  = count > len ? len : count;
        uint256 start = len - size;
        usdtAmounts = new uint256[](size);
        mvtAmounts  = new uint256[](size);
        timestamps  = new uint256[](size);
        types       = new uint8[](size);
        for (uint256 i = 0; i < size; i++) {
            TokenTransfer storage t = history[start + i];
            usdtAmounts[i] = t.usdtAmount;
            mvtAmounts[i]  = t.mvtAmount;
            timestamps[i]  = t.timestamp;
            types[i]       = t.transferType;
        }
    }

    function withdrawUSDT(address to, uint256 amount) external onlyOwner {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        bool success = usdtToken.transfer(to, amount);
        if (!success) revert TransferFailed();
    }
}

contracts/MvaultView.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.27;

/**
 * @title  MvaultView
 * @notice Read-only helper contract that re-exposes view functions removed
 *         from MvaultContract to stay under the EIP-170 24 576-byte limit.
 *
 *         Deploy once, point at the live MvaultContract + BoardHandler.
 *         No state is written here — every function is a pure view delegate.
 */

// ── Minimal interfaces ────────────────────────────────────────────────────────

interface IMvault {
    function totalUsers()  external view returns (uint256);
    function reservePool() external view returns (uint256);
    function adminPool()   external view returns (uint256);
    function rankPool()    external view returns (uint256);
    function communityPool() external view returns (uint256);
    function mvaultToken() external view returns (address);
    function usdtToken()   external view returns (address);
    function boardHandler()  external view returns (address);
    function stakingModule() external view returns (address);
    function allUsers(uint256 index) external view returns (address);
    function users(address u) external view returns (
        bool    isRegistered,
        bool    isActive,
        address sponsor,
        uint256 directCount,
        address binaryParent,
        bool    placedLeft,
        address leftChild,
        address rightChild,
        uint256 leftSubVolume,
        uint256 rightSubVolume,
        uint256 mvtBalance,
        uint256 totalReceived,
        uint256 totalSold,
        uint256 incomeLimit,
        uint256 usdtBalance,
        uint256 rebirthPool,
        uint256 totalUsdtEarned,
        uint256 btcPoolBalance,
        uint256 totalBtcEarned,
        uint256 packagePrice,
        uint256 incomeLimitCap,
        address mainAccount,
        uint256 rebirthCount,
        uint8   rank,
        uint256 teamSalesUsdt,
        uint256 joinedAt,
        string  memory displayName,
        string  memory email,
        string  memory phone,
        string  memory country,
        bool    profileSet
    );
}

interface IBoardHandler {
    function getBoardPrice(uint256 boardLevel)                        external view returns (uint256);
    function getBoardQueueLength(uint256 boardLevel)                  external view returns (uint256);
    function getBoardCurrentIndex(uint256 boardLevel)                 external view returns (uint256);
    function getBoardMatrixInfo(uint256 boardLevel, uint256 index)
        external view returns (address owner, uint256 filledCount, bool completed);
}

interface IStaking {
    function MIN_STAKE_USDT() external view returns (uint256);
    function LOCK_DURATION()  external view returns (uint256);
    function FLEX_CAP_MULT()  external view returns (uint256);
}

interface IERC20Minimal {
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
}

// ── MvaultView ────────────────────────────────────────────────────────────────

contract MvaultView {

    IMvault public immutable mvault;

    constructor(address _mvault) {
        require(_mvault != address(0), "zero address");
        mvault = IMvault(_mvault);
    }

    // ── Helpers ───────────────────────────────────────────────────────────────

    function _board() internal view returns (IBoardHandler) {
        address bh = mvault.boardHandler();
        require(bh != address(0), "board handler not set");
        return IBoardHandler(bh);
    }

    function _staking() internal view returns (IStaking) {
        address sm = mvault.stakingModule();
        require(sm != address(0), "staking module not set");
        return IStaking(sm);
    }

    // ── Aliases for removed MvaultContract functions ──────────────────────────

    function getAllUsersCount() external view returns (uint256) {
        return mvault.totalUsers();
    }

    /// @notice Returns (communityPool, reservePool, adminPool) from MvaultContract.
    function getPoolBalances() external view returns (
        uint256 community,
        uint256 reserve,
        uint256 admin
    ) {
        community = mvault.communityPool();
        reserve   = mvault.reservePool();
        admin     = mvault.adminPool();
    }

    /// @notice Returns all pool balances including rankPool.
    function getAllPoolBalances() external view returns (
        uint256 community,
        uint256 reserve,
        uint256 admin,
        uint256 rank
    ) {
        community = mvault.communityPool();
        reserve   = mvault.reservePool();
        admin     = mvault.adminPool();
        rank      = mvault.rankPool();
    }

    /// @notice MVT ERC-20 tokens held by MvaultContract.
    function getMvtContractBalance() external view returns (uint256) {
        address mvt = mvault.mvaultToken();
        return IERC20Minimal(mvt).balanceOf(address(mvault));
    }

    /// @notice USDT ERC-20 balance held by MvaultContract.
    function getUsdtContractBalance() external view returns (uint256) {
        address usdt = mvault.usdtToken();
        return IERC20Minimal(usdt).balanceOf(address(mvault));
    }

    // ── Package / income constants ────────────────────────────────────────────

    uint256 public constant PRICE_STARTER  =  55 * 1e18;
    uint256 public constant INCOME_STARTER = 165 * 1e18;
    uint256 public constant PRICE_PRO      = 130 * 1e18;
    uint256 public constant INCOME_PRO     = 390 * 1e18;

    function PACKAGE_PRICE() external pure returns (uint256) { return PRICE_PRO; }
    function INCOME_LIMIT()  external pure returns (uint256) { return INCOME_PRO; }

    function getPackageParams(uint8 pkg) external pure returns (uint256 price, uint256 incomeCap) {
        if (pkg == 1) return (PRICE_STARTER, INCOME_STARTER);
        if (pkg == 2) return (PRICE_PRO,     INCOME_PRO);
        revert("invalid package");
    }

    // ── Staking constants ─────────────────────────────────────────────────────

    function getLockDuration() external view returns (uint256) { return _staking().LOCK_DURATION();  }
    function getMinStakeUsdt() external view returns (uint256) { return _staking().MIN_STAKE_USDT(); }
    function getFlexCapMult()  external view returns (uint256) { return _staking().FLEX_CAP_MULT();  }

    // ── Board handler delegates ───────────────────────────────────────────────

    function getBoardPrice(uint256 boardLevel) external view returns (uint256) {
        return _board().getBoardPrice(boardLevel);
    }

    function getBoardQueueLength(uint256 boardLevel) external view returns (uint256) {
        return _board().getBoardQueueLength(boardLevel);
    }

    function getBoardCurrentIndex(uint256 boardLevel) external view returns (uint256) {
        return _board().getBoardCurrentIndex(boardLevel);
    }

    function getBoardMatrixInfo(uint256 boardLevel, uint256 index)
        external view returns (address owner, uint256 filledCount, bool completed)
    {
        return _board().getBoardMatrixInfo(boardLevel, index);
    }

    // ── Batch board snapshot ──────────────────────────────────────────────────

    struct BoardTierSnapshot {
        uint256 level;
        uint256 price;
        uint256 queueLength;
        uint256 currentIndex;
    }

    function getBoardSnapshot(uint256 fromLevel, uint256 toLevel)
        external view returns (BoardTierSnapshot[] memory tiers)
    {
        IBoardHandler bh = _board();
        uint256 count = toLevel >= fromLevel ? toLevel - fromLevel + 1 : 0;
        tiers = new BoardTierSnapshot[](count);
        for (uint256 i = 0; i < count; i++) {
            uint256 lvl = fromLevel + i;
            tiers[i] = BoardTierSnapshot({
                level:        lvl,
                price:        bh.getBoardPrice(lvl),
                queueLength:  bh.getBoardQueueLength(lvl),
                currentIndex: bh.getBoardCurrentIndex(lvl)
            });
        }
    }

    // ── User-list helpers ─────────────────────────────────────────────────────

    function getUserSlice(uint256 offset, uint256 limit)
        external view returns (address[] memory slice)
    {
        uint256 total = mvault.totalUsers();
        if (offset >= total) return new address[](0);
        uint256 end = offset + limit > total ? total : offset + limit;
        slice = new address[](end - offset);
        for (uint256 i = 0; i < slice.length; i++) {
            slice[i] = mvault.allUsers(offset + i);
        }
    }

    // ── Rank batch reader ─────────────────────────────────────────────────────

    struct RankBatchEntry {
        bool    isActive;
        uint8   rank;
        address sponsor;
        uint256 directCount;
        uint256 teamSalesUsdt;
        uint256 leftSubVolume;
        uint256 rightSubVolume;
    }

    function getRankBatch(address[] calldata addrs)
        external view returns (RankBatchEntry[] memory data)
    {
        data = new RankBatchEntry[](addrs.length);
        for (uint256 i = 0; i < addrs.length; i++) {
            (
                bool _reg, bool _act,
                address _sp, uint256 _dc, address _bp, bool _pl, address _lc, address _rc,
                uint256 _l, uint256 _r,
                uint256 _mb, uint256 _tr, uint256 _ts, uint256 _il, uint256 _ub,
                uint256 _rp, uint256 _tue, uint256 _bb, uint256 _tbe,
                uint256 _pp, uint256 _ilc, address _ma, uint256 _rb,
                uint8 _rk, uint256 _tsu, uint256 _ja,
                string memory _dn, string memory _em, string memory _ph, string memory _co,
                bool _prs
            ) = mvault.users(addrs[i]);
            _bp; _pl; _lc; _rc;
            _mb; _tr; _ts; _il; _ub; _rp; _tue; _bb; _tbe;
            _pp; _ilc; _ma; _rb; _ja;
            _dn; _em; _ph; _co; _prs;
            if (!_reg) continue;
            data[i] = RankBatchEntry({
                isActive:       _act,
                rank:           _rk,
                sponsor:        _sp,
                directCount:    _dc,
                teamSalesUsdt:  _tsu,
                leftSubVolume:  _l,
                rightSubVolume: _r
            });
        }
    }

    // ── Board eligibility check ───────────────────────────────────────────────

    function canEnterBoard(address _user) external view returns (
        bool eligible, uint256 btcBalance, uint256 boardPrice
    ) {
        address bh = mvault.boardHandler();
        if (bh == address(0)) return (false, 0, 0);
        // users() returns 31 fields; pos 2=isActive, pos 18=btcPoolBalance
        (
            , bool _act, , , , , , , , ,
            , , , , , , , uint256 _btc,
            , , , , , , , ,
            string memory _s1, string memory _s2, string memory _s3, string memory _s4,
        ) = mvault.users(_user);
        _s1; _s2; _s3; _s4;
        btcBalance = _btc;
        boardPrice = IBoardHandler(bh).getBoardPrice(1);
        eligible   = _act && btcBalance >= boardPrice;
    }

    // ── Contract addresses ────────────────────────────────────────────────────

    function getMvaultAddress()       external view returns (address) { return address(mvault); }
    function getMvtTokenAddress()     external view returns (address) { return mvault.mvaultToken(); }
    function getUsdtTokenAddress()    external view returns (address) { return mvault.usdtToken(); }
    function getBoardHandlerAddress() external view returns (address) { return mvault.boardHandler(); }
    function getStakingAddress()      external view returns (address) { return mvault.stakingModule(); }
}

